(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-era-entropy-guided-visual-token-prun-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-1\">一 · 一个在线服务的现场：预填被视觉 token 压垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-2\">二 · 旧方案的主流做法：按注意力权重排序剪枝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-3\">三 · 为什么非改不可：三重代价叠加在 Blackwell 服务上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-4\">四 · ERA 的两个动作：熵引导保留与注意力整流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-5\">五 · 旧方案与 ERA 的工程对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-6\">六 · 判断这条路径是否值得接进你的栈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-7\">七 · 在线多模态服务的预填队列与旧剪枝的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-8\">八 · 请求形态：视觉token如何定义负载的“形状”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-9\">九 · 并发与批大小：压缩后重算显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-10\">十 · SLO：首token延迟是主战场，解码收益有限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-11\">十一 · 长尾：视频请求与批内延迟方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-12\">十二 · 方案反过来限制负载：K与整流开关如何塑造可服务请求集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-13\">十三 · 负载形态如何界定 ERA 的可用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-14\">十四 · 熵估计与整流在 kernel 层的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-15\">十五 · 数据类型选择：从 BF16 到 NVFP4 的逐段取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-16\">十六 · 累加精度与误差传播：熵排序为何不能跨层直接比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-18\">十八 · 一个具体例子：单帧图像请求的算子时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-19\">十九 · 熵估计与整流 kernel 的融合边界：精度、显存与低延迟 SLO 下的失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-20\">二十 · 显存账本的三层结构与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-21\">二十一 · 分页 KV cache 与压缩后序列长度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-22\">二十二 · 带宽瓶颈的位置：预填是算力，解码是带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-23\">二十三 · 复用、压缩、卸载：三条省显存的路怎么排优先级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-24\">二十四 · HBM3e 容量怎么算，以及整流在并行切分下的显存一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-25\">二十五 · 显存账本与带宽拐点：ERA 压缩后 KV 预算的可复算边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-26\">二十六 · 压缩后序列进入调度器的那一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-27\">二十七 · chunked prefill 与熵估计的算子位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-28\">二十八 · 优先级、抢占与整流的一致性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-29\">二十九 · 分离式预填/解码下的视觉侧归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-30\">三十 · 吞吐与尾延迟的取舍落在 K 上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-31\">三十一 · 当 ERA 进入连续批处理：预算、抢占与整流归一化的分片一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-32\">三十二 · 并行切分的四个维度与视觉 token 的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-33\">三十三 · NVLink 5 与 NVSwitch：机内带宽不是无限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-34\">三十四 · All-to-All 与 EP：MoE 层的通信形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-35\">三十五 · NIXL 传输与分离式部署</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-36\">三十六 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-37\">三十七 · 整流归一化的并行切分代价与通信临界点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-38\">三十八 · 精度塌陷的三种签名与熵尺度错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-39\">三十九 · OOM 与批抖动的耦合定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-40\">四十 · 尾延迟：熵估计的算子开销落在关键路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-41\">四十一 · 静默降级：没有报错但质量在滑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-42\">四十二 · 诊断顺序与回滚的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-43\">四十三 · 失效边界：从熵排序偏差到整流归一化在切分下的不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-44\">四十四 · 口径的三层结构：模型档、硬件档、负载档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-45\">四十五 · 指标各自的敏感面：TTFT、TPOT、吞吐、显存、功耗</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-46\">四十六 · 熵估计与整流的算子开销如何进入口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-47\">四十七 · 哪些提升不可比：四类典型错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-48\">四十八 · 视频多帧负载下的口径特殊性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-49\">四十九 · 基准口径与失效边界：ERA 的收益在什么条件下才成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-50\">五十 · 迁移到非 Qwen-VL 系架构：熵的语义先要重新标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-51\">五十一 · 整流在张量并行与分页 KV 下的实现边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-52\">五十二 · 视频与多帧：逐帧独立剪枝的时序断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-53\">五十三 · 规模上限：K 的下界由什么决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-54\">五十四 · 跨领域迁移的取舍表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-55\">五十五 · 与量化、投机解码叠加时的相互作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-era-entropy-guided-visual-token-prun-2026-sec-56\">五十六 · 迁移与边界：从插件假设到规模上限</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:542px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 541.9 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像/视频经预处理送入视觉编码器，输出原始视觉token序列及其维度。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对视觉token逐层或末层计算注意力熵，得到熵分数并排序。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按预设token预算执行熵引导剪枝：高熵token保留，低熵token…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对被保留token的跨模态注意力做整流修正，重新归一化注意力权重。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">整流后的视觉token与文本token拼接，进入LLM解码并写入KV …</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批调度器按压缩后序列长度重算显存预算，动态调整并发批大小。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-1\">一 · 一个在线服务的现场：预填被视觉 token 压垮</h3>\n<p>设想一个跑在 GB200 NVL72 上的多模态在线服务：前端是文档问答与截图理解，单请求带一张高分辨率图，视觉编码器切出数千个 patch token 送进 LLM。批调度器按每请求的 KV cache 占用估算并发，而视觉 token 与文本 token 一样要占 KV 页。当图像分辨率翻倍、或请求里带多帧视频时，视觉 token 数随分辨率与帧数线性增长，KV cache 预算被迅速吃掉，连续批处理被迫压低并发批大小。首 token 延迟（TTFT）由预填阶段主导，而预填的计算量正比于序列长度——视觉 token 是这条链路上最容易被压缩、也最值得压缩的部分。这就是 ERA 要处理的问题现场：不是模型不够聪明，而是预填与显存预算被视觉 token 挤占，服务侧的 SLO 在图像密集负载下先崩。</p>\n<p>把代价写清楚：设视觉 token 数为 <span class=\"formula\">$$N_v$$</span>，压缩到预算 <span class=\"formula\">$$K$$</span> 后，预填阶段注意力计算量大致按 <span class=\"formula\">$$O((N_v+N_t)^2)$$</span> 降到 <span class=\"formula\">$$O((K+N_t)^2)$$</span>（<span class=\"formula\">$$N_t$$</span> 为文本 token），KV cache 占用按 <span class=\"formula\">$$N_v$$</span> 线性下降。这两项直接决定批调度器能开多大并发。举例：一个以文档截图为主的请求，若视觉 token 占序列长度的大头，把 <span class=\"formula\">$$N_v$$</span> 压到 <span class=\"formula\">$$K$$</span> 就能把预填延迟和每请求显存同时压低，调度器随即提高批大小，吞吐上升。但解码阶段每步只处理一个 token，收益有限——端到端加速取决于视觉 token 在总序列中的占比，这是判断任何视觉剪枝方案是否值得部署的第一条工程判据。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-2\">二 · 旧方案的主流做法：按注意力权重排序剪枝</h3>\n<p>在 ERA 之前，推理栈里视觉 token 压缩的主流做法有两类：一类是按跨模态注意力分数给视觉 token 排序，保留分数高的、剪掉分数低的；另一类是按 token 特征相似度做合并（merge），把相近的 token 聚成一个。前者实现简单，只需在跨模态注意力层读一次权重、排序、按预算截断，几乎不引入额外算子；后者在视觉侧做聚类，能保住局部结构但合并后的 token 语义被平均化。两者共同的假设是：注意力权重高的 token 更重要。这个假设在低熵层大致成立，但在高熵层失效——注意力分布弥散，权重被摊薄到大量 token 上，排序结果接近噪声，按它剪枝等于随机丢弃细粒度语义。</p>\n<p>用公式说清这个失效机制。设某层视觉 token 的注意力分布为 <span class=\"formula\">$$p_{ij}$$</span>，其熵为</p>\n<div class=\"formula\">$$\\mathcal{S}_i = -\\sum_{j} p_{ij}\\log p_{ij}$$</div>\n<p>熵高意味着该 token 的注意力分散在多个位置上，它承载的是\"需要跨位置整合\"的细粒度信息；熵低意味着注意力集中、信息冗余。按原始权重 <span class=\"formula\">$$a_i$$</span> 排序，会把弥散分布下权重被摊薄的 token 判为不重要而剪除——这正是高熵层误删的来源。剪枝之后还有第二重损伤：剩余 token 的注意力权重没有重新归一化，注意力质量继续流向已被删除的位置，跨模态对齐信号被稀释，精度出现塌陷式下降。旧方案只做了\"删\"，没做\"补\"，这是它非改不可的根本原因。</p>\n<p>代价层面，旧方案的算子开销低（一次排序），但精度代价高：为了守住精度，服务侧只能把 token 预算 <span class=\"formula\">$$K$$</span> 设得保守，压缩比上不去，预填延迟与 KV cache 的收益被抵消。这就是工程上的死结——想省显存就得狠剪，狠剪就掉精度，掉精度就得回退预算。ERA 的切入点正是把这个死结从\"排序准则\"和\"剪后补偿\"两端同时解开。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-3\">三 · 为什么非改不可：三重代价叠加在 Blackwell 服务上</h3>\n<p>第一重是显存与带宽。视觉 token 与文本 token 共享分页 KV cache，页表按 token 数分配。高分辨率图像下单请求的视觉 KV 占用可达文本部分的数倍，批内多个这样的请求叠加，显存迅速见顶，调度器只能降并发。第二重是预填延迟。预填是计算密集阶段，序列长度直接进注意力矩阵规模，视觉 token 翻倍意味着预填时间近似按平方增长的那部分被放大，TTFT 的 SLO 最先被击穿。第三重是功耗与算力错配：视觉编码器与 LLM 的算力需求形态不同，若视觉 token 不做压缩，LLM 侧的预填算力被大量冗余 token 消耗，NVFP4/FP8 量化省下来的算力又被序列长度吃回去。</p>\n<p>这三重代价在 Blackwell 上还有一个特殊约束：tcgen05 与 2-SM MMA 的高效区间偏好规整的矩阵形状，序列长度是注意力 kernel 分块的自然维度。视觉 token 数不可控时，预填阶段的 kernel 分块效率与 TMEM 占用都随请求波动，服务侧的容量规划只能按最坏情况留余量。把 <span class=\"formula\">$$N_v$$</span> 压到固定预算 <span class=\"formula\">$$K$$</span>，等于把预填形状变成可预测的常量，这对容量规划和 SLO 稳定性是直接收益。举例：一个视频帧序列请求，逐帧 token 数不均，若不压缩，批内延迟方差被帧数放大；压缩到统一预算后，批调度器可以用同一套显存预算估算并发，延迟方差收敛。</p>\n<p>所以\"非改不可\"不是精度洁癖，而是服务经济学：旧方案为了保精度把 <span class=\"formula\">$$K$$</span> 设高，压缩比低，显存与预填收益不足以覆盖部署复杂度；要真正把视觉 token 压下去，必须换一个在高熵层也稳的重要性度量，并且补上剪后的注意力归一化。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-4\">四 · ERA 的两个动作：熵引导保留与注意力整流</h3>\n<p>ERA 把重要性度量从原始注意力权重换成层内注意力熵。对每个视觉 token 算熵分数 <span class=\"formula\">$$\\mathcal{S}_i$$</span>，熵高者优先保留、熵低者优先剪除或合并，按预算取 top-k：</p>\n<div class=\"formula\">$$\\mathcal{K}=\\mathrm{TopK}\\left(\\{\\mathcal{S}_i\\}_{i=1}^{N_v}, K\\right)$$</div>\n<p>这一步的工程含义是：剪枝准则不再依赖注意力权重的绝对大小，而是依赖分布的弥散程度，从而避开高熵层权重摊薄导致的误判。第二个动作是整流：对被保留 token 的跨模态注意力做掩码与重新归一化，</p>\n<div class=\"formula\">$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}}$$</div>\n<p>把流向已剪除位置的注意力质量收回并重新分配到有效 token 集合上。注意这是前向修正，不改 LLM 权重，因此可以作为推理期插件挂在视觉编码器输出与跨模态注意力之间，与 NVFP4/FP8 量化、分页 KV cache、连续批调度共存。部署时只需配置两个旋钮：token 预算 <span class=\"formula\">$$K$$</span> 与整流开关。</p>\n<p>代价必须摊开讲。熵估计是额外的前向计算加一次排序，若不能融合进视觉编码器或注意力 kernel，这部分算子延迟会直接加在 TTFT 上，在低延迟 SLO 下可能抵消剪枝带来的预填收益——这是 ERA 最主要的工程风险，也是判断它能否落地的关键：整流与熵估计能否融合进注意力 kernel，决定了端到端是净赚还是净亏。另一个边界是极低 <span class=\"formula\">$$K$$</span> 下整流只能重分配注意力，无法恢复被剪除 token 承载的细粒度信息，压缩比越高精度风险越大。举例：一个细粒度图表问答请求，若预算压得过狠，整流后注意力虽已归一化，但被删掉的刻度 token 信息不可恢复，答案精度下降——这类请求的 <span class=\"formula\">$$K$$</span> 需要按任务类型分档配置，而不是全局一个值。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-5\">五 · 旧方案与 ERA 的工程对照</h3>\n<table class=\"mini\"><thead><tr><th>维度</th><th>按注意力权重排序剪枝</th><th>ERA 熵引导 + 整流</th></tr></thead><tbody>\n<tr><td>重要性准则</td><td>原始注意力分数 <span class=\"formula\">$$a_i$$</span></td><td>层内注意力熵 <span class=\"formula\">$$\\mathcal{S}_i$$</span></td></tr>\n<tr><td>高熵层行为</td><td>权重摊薄，排序近噪声，误删细粒度 token</td><td>熵高者保留，避开摊薄误判</td></tr>\n<tr><td>剪后补偿</td><td>无，注意力质量流向已删位置</td><td>掩码 + 重新归一化，质量收回有效集合</td></tr>\n<tr><td>额外算子</td><td>一次排序，开销低</td><td>熵估计 + 排序 + 整流，需 kernel 融合</td></tr>\n<tr><td>精度—压缩权衡</td><td>为保精度只能设高 <span class=\"formula\">$$K$$</span>，压缩比低</td><td>低 <span class=\"formula\">$$K$$</span> 下维持对齐，但极低预算仍有信息损失</td></tr>\n<tr><td>部署侵入性</td><td>推理期，无权重改动</td><td>推理期插件，无权重改动，可与量化/分页 KV 叠加</td></tr>\n</tbody></table>\n<p>这张表里的关键判断是：旧方案的低算子开销是假象——它把成本转移到了精度上，服务侧只能用保守预算买单；ERA 把成本显性化为熵估计与整流的算子开销，换取更低的 <span class=\"formula\">$$K$$</span> 与更稳的对齐。对 Blackwell 服务而言，前者是\"省了 kernel 时间、亏了显存与并发\"，后者是\"多花一点前向、换回预填延迟与 KV 预算\"。哪个更划算，取决于视觉 token 在序列中的占比与 SLO 的延迟余量。</p>\n<p>还有一个部署细节值得在问题现场就定下来：整流归一化在张量并行切分下必须保证全局求和一致，否则各分片各自归一化会破坏跨模态对齐。这意味着整流不能简单地在每个 rank 上独立做，需要与注意力的 all-reduce 语义对齐——这是把 ERA 接进现有并行拓扑时必须先解决的实现问题，而不是精度问题。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-6\">六 · 判断这条路径是否值得接进你的栈</h3>\n<p>把问题收敛成一个工程判断：如果你的在线服务里视觉 token 占序列长度的大头、TTFT 是主 SLO、显存被 KV cache 顶住，那么视觉 token 压缩的收益是结构性的，旧方案的精度—压缩死结必须解开，ERA 的熵准则与整流是当前材料下合理的解法方向。反之，若负载以长文本为主、视觉 token 占比小，压缩带来的预填收益有限，而熵估计的额外算子开销会直接体现在 TTFT 上，接入的性价比就低。第二个判断点是 kernel 融合：熵估计与整流若能并入视觉编码器或注意力 kernel，额外开销被摊薄，ERA 是净收益；若只能作为独立算子串在前向链路里，低延迟 SLO 下要谨慎，先在小流量上量出算子开销与预填收益的差值再决定压缩比。</p>\n<p>第三个判断点是预算策略：<span class=\"formula\">$$K$$</span> 不应是全局常量，而应按请求类型分档——细粒度图表、文档截图需要更高预算，场景描述类可以更低。视频多帧输入下各帧熵分布不均，逐帧独立剪枝可能破坏帧间时序一致性，材料未给出该场景的实测数据，接入时应把帧间熵排序的稳定性作为单独的验证项。最后，材料未给出数据集、基线、精度与吞吐的具体数字，任何加速比与精度保持幅度都不能从现有材料核验；能确定的只有机制层面的收益来源（<span class=\"formula\">$$N_v \\to K$$</span> 降低预填计算与 KV 占用）与代价来源（熵估计与整流的算子开销、极低预算下的信息损失），实际部署必须用自家负载把这两条曲线量出来再定 <span class=\"formula\">$$K$$</span> 与整流开关的默认值。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-7\">七 · 在线多模态服务的预填队列与旧剪枝的失效边界</h3>\n<p>设想一个面向在线客服的图文问答服务：请求以图像加短问题为主，图像经预处理后切成patch送入视觉编码器，输出N_v个视觉token，与文本token拼接后进入LLM预填。旧方案的典型做法是在视觉编码器输出端按注意力权重排序，取top-k保留、其余丢弃或与邻近token相似度合并，把序列长度从N_v压到K。问题在于这条链路把“注意力大”等同于“信息重要”，而跨模态注意力在高熵层的分布本就弥散——权重被摊薄到大量token上，排序结果接近随机，承载细粒度语义的少数token很容易被误删。剪枝之后，跨模态注意力仍按原分布归一化，质量流失到已删除位置上，对齐信号被破坏，精度塌陷往往在长尾细粒度问题上先暴露，而不是在平均指标上。</p>\n<p>系统代价是双重的。收益侧：视觉token从N_v降到K，预填阶段的计算量与KV cache占用同步下降，分页KV cache的页表压力减轻，批调度器可按压缩后序列长度重算每请求显存预算并提高并发。代价侧：旧方案要么依赖注意力分数（需在注意力层内取数，与算子融合耦合），要么依赖相似度合并（需额外的token间距离计算与聚类），两者都引入额外前向开销；若这些算子无法融合进视觉编码器或注意力kernel，额外延迟会吃掉预填收益。更关键的是解码阶段几乎不受益——端到端加速取决于视觉token在总序列中的占比，图像分辨率越高、文本越短，占比越大，收益才越明显；反之在长文本对话中，压缩视觉token对首token延迟的改善有限。</p>\n<p>失效条件可以写成一条判断：当层内注意力熵偏高时，按权重排序的保留集合与真实重要集合的交集缩小，剪枝误差随压缩比上升而放大。设保留预算K，整流前的注意力质量损失可定性表示为被剪位置权重之和占原归一化质量的比例；旧方案不做补偿，这一比例直接转化为跨模态失配。ERA的切入点正是把重要性度量换成熵<span class=\"formula\">$$\\mathcal{S}_i = -\\sum_{j} p_{ij}\\log p_{ij}$$</span>并按<span class=\"formula\">$$\\mathcal{K}=\\mathrm{TopK}\\left(\\{\\mathcal{S}_i\\}_{i=1}^{N_v}, K\\right)$$</span>保留高熵token，再对保留位置做整流<span class=\"formula\">$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}}$$</span>。但这条路径有自己的边界：熵估计本身是额外前向计算与排序开销，低延迟SLO下若不能融合进kernel，收益会被抵消；极低K时整流只能重分配注意力，无法恢复被剪除的细粒度信息；视频多帧输入下逐帧独立剪枝还会带来帧间时序不一致，批内延迟方差随之上升。工程判断因此落在两处：熵估计与整流能否融合进注意力kernel，以及服务侧能否按K与整流开关做灰度配置而不触碰主干权重。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>旧方案（按注意力权重/相似度合并）</th><th>ERA的边界</th></tr></thead><tbody><tr><td>重要性准则</td><td>权重排序，高熵层易误删</td><td>熵排序，需跨层尺度校准</td></tr><tr><td>剪枝后补偿</td><td>无，注意力质量流失</td><td>整流归一化，仅重分配</td></tr><tr><td>额外开销</td><td>取数或距离计算</td><td>熵估计+排序，需kernel融合</td></tr><tr><td>收益阶段</td><td>预填为主</td><td>预填为主，解码有限</td></tr></tbody></table>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-8\">八 · 请求形态：视觉token如何定义负载的“形状”</h3>\n<p>在Blackwell服务侧，MLLM请求的负载形态不是由请求数决定的，而是由每个请求携带的视觉token总量决定的。视觉编码器把图像切成patch、视频按帧展开后，输出序列长度N_v随分辨率与帧数线性增长；文本侧长度通常只有几十到几百token，视觉侧却可以轻易占据序列的绝大部分。这意味着批调度器面对的是一组长度极不均匀的请求：纯文本请求、单图请求、多图请求、短视频请求、长视频请求混在同一队列里，它们的预填计算量与KV cache占用相差一个数量级以上。ERA的介入点恰好落在这个“形状”上——它把每请求的视觉长度从N_v改写为K，等于在请求进入批之前就改变了负载的粒度。</p>\n<p>测量口径必须可核查，否则“压缩比”只是口号。建议在服务入口按请求记录四个量：原始视觉token数N_v、文本token数N_t、压缩后视觉token数K、以及压缩比ρ=K/N_v。这四个量构成请求的负载指纹，后续所有延迟与显存指标都应能按ρ分桶回溯。注意N_v的统计必须区分图像与视频：图像请求的N_v由分辨率决定，分布相对集中；视频请求的N_v由帧数×每帧token数决定，分布长尾极重，少数长视频请求可能占据单批显存预算的绝大部分。</p>\n<p>负载形态直接决定ERA的收益上限。设单请求预填计算量近似正比于(N_v+N_t)，则视觉侧压缩带来的预填缩减比例为(N_v−K)/(N_v+N_t)。当N_t相对N_v可忽略时，该比例趋近1−ρ；当文本占比高时，收益被稀释。这就是为什么ERA的端到端加速“取决于视觉token占比”——它不是一句定性描述，而是可以用上述比例在请求级算出来的量。工程判断很直接：若某服务的视觉token占比中位数低于某个阈值，压缩视觉侧对首token延迟的改善会被文本预填与解码开销淹没。</p>\n<div class=\"formula\">$$\\text{prefill\\_saving} = \\frac{N_v - K}{N_v + N_t} = \\frac{(1-\\rho)N_v}{N_v + N_t}$$</div>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-9\">九 · 并发与批大小：压缩后重算显存预算</h3>\n<p>连续批处理下，批大小不是自由参数，而是由每请求KV cache占用与显存预算共同约束的因变量。视觉token写入KV cache后，每层每token的KV占用为2×d_head×n_kv_head×字节数；压缩把视觉侧token数从N_v降到K，直接按比例削减这部分占用。批调度器必须在请求准入时用压缩后的长度重算每请求页数与显存预算，再决定能塞进多少个请求。若调度器仍按原始N_v预留显存，压缩带来的并发提升就被浪费；若按K预留却在整流前误用了原始长度，则会出现页表与实际序列不一致。</p>\n<p>可核查的口径是“每请求KV页数”与“批内视觉token总数”。前者用于显存核算，后者用于判断批是否被单个长视频请求撑爆。设批内请求集合为B，则批的视觉KV占用正比于Σ_{i∈B}K_i。调度器应把ΣK_i作为准入约束而非请求数约束——因为一个ρ接近1的长视频请求与十个ρ很小的图像请求可能占用相同的视觉显存。ERA在此处的价值是把K_i变成服务侧可配置的量：调低K即调低每请求显存占用，从而抬高并发上限，代价是精度风险随压缩比上升。</p>\n<p>具体例子：一个视频请求原始N_v很大，若ρ取中等水平，其视觉KV占用按比例下降，调度器可把这部分省出的显存分配给数个图像请求，批内请求数上升而批内视觉token总数受控。但要注意，批内延迟由最慢请求决定，长视频请求的预填仍是批的临界路径；压缩只缩短了它的预填，不改变它相对其他请求更长的结构。因此并发提升的实测口径应同时报告批内请求数与批内最长请求的预填时延，二者缺一不可。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-10\">十 · SLO：首token延迟是主战场，解码收益有限</h3>\n<p>ERA的收益集中在预填阶段，这一点必须在SLO口径上说清楚。首token延迟（TTFT）由预处理、视觉编码、熵估计与排序、剪枝、整流、LLM预填共同构成；压缩缩短的是视觉token进入LLM后的预填长度与KV写入量，但熵估计本身是新增的前向计算与排序开销。因此TTFT的净变化是“剪枝收益减去熵估计开销”，而不是单调改善。若熵估计不能融合进视觉编码器或注意力kernel，额外算子延迟会直接吃掉预填缩减，这在低延迟SLO下是主要工程风险。</p>\n<p>可核查的测量应把TTFT拆成至少三段：视觉侧（编码+熵估计+排序+剪枝）、整流段、LLM预填段。只有分段计时才能判断收益来自哪里、开销落在哪里。解码阶段（TPOT或每token延迟）的收益有限，因为解码时KV cache已固定，压缩只减少了注意力读取的视觉位置数，对解码算力的影响远小于预填。SLO若以TPOT为主，ERA的吸引力下降；若以TTFT为主，压缩比ρ就是直接可调的杠杆。</p>\n<p>公式上，TTFT的净变化可写成剪枝前后预填时间之差减去熵估计开销：</p>\n<div class=\"formula\">$$\\Delta \\text{TTFT} \\approx t_{\\text{prefill}}(N_v) - t_{\\text{prefill}}(K) - t_{\\text{entropy}} - t_{\\text{rect}}$$</div>\n<p>工程判断：只有当t_entropy+t_rect显著小于预填缩减时，ERA才在TTFT口径上成立。服务侧应把整流开关与熵估计所在层作为两个独立配置项，分别测量其耗时占比，而不是笼统报告“端到端加速”。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-11\">十一 · 长尾：视频请求与批内延迟方差</h3>\n<p>长尾是负载形态里最容易被忽略、又最影响SLO达标率的部分。视频请求的N_v随帧数增长，其分布尾部极重；更麻烦的是请求内各帧的视觉token熵分布不均，逐帧独立剪枝会让不同帧保留的token数不一致，进而造成帧间时序信息不一致。材料明确指出这一时序一致性未获实测验证，因此服务侧不能假定压缩对视频是“帧间均匀”的。可核查的口径包括：按帧数分桶的请求占比、每桶的ρ分布、以及批内延迟的方差（而非仅均值）。</p>\n<p>批内延迟方差直接决定SLO达标率。若批内混入一个长视频请求，其预填时间是批的临界路径，其他请求的TTFT被它拖长；压缩虽缩短了该请求的预填，但只要它仍是批内最长者，方差改善就有限。调度策略上可考虑按N_v分桶准入，把长视频请求单独成批或限制其与短请求混批，避免长尾请求把整批的TTFT分布拉坏。ERA的K配置也可按请求类型分档：图像请求用较激进的小K，视频请求用较保守的大K以保留帧间信息，这比全局单一K更符合负载形态。</p>\n<p>具体例子：同一批内若一个长视频请求的压缩后视觉长度仍远大于其余请求之和，则批的视觉KV占用由它主导，提高并发对整批TTFT的帮助被它抵消。此时正确的口径不是“平均压缩比”，而是“批内最大请求的压缩后长度占批预算的比例”。这个比例高，说明批被长尾绑架，应调整准入而非继续调低K。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-12\">十二 · 方案反过来限制负载：K与整流开关如何塑造可服务请求集</h3>\n<p>负载塑造方案，方案也反过来限制负载。ERA把K暴露为服务侧配置，等于给可服务请求集加了一个隐式上限：当请求的N_v极大而K被压得很低时，ρ趋近于零，整流只能重分配注意力权重，无法恢复被剪除token承载的细粒度信息，精度下降风险随压缩比上升而增大。材料未给出该边界的具体数值，因此服务侧必须用可核查的口径自己划定边界：按ρ分桶统计精度或人工评估通过率，找到ρ的可用区间，再把K配置限制在该区间内。超出区间的请求应被拒绝、降级或走高ρ通道，而不是静默压缩。</p>\n<p>整流开关同样塑造负载。整流只作用于视觉侧注意力、不改变LLM权重，但它在张量并行切分下需要保证全局求和一致，否则各分片归一化结果不一致会破坏跨模态对齐。这意味着开启整流对并行拓扑有约束：跨模态注意力层的归一化必须跨TP rank做全局归约，通信量随TP增大而增加。服务侧若为吞吐把TP切得很细，整流开关的代价会上升；若为低延迟保持较小TP，则并发上限受单卡显存约束。这是一个可以用“整流开销随TP rank数增长”来核查的权衡，而不是笼统的“插件可叠加”。</p>\n<p>最后，熵估计所在层也是一个限制负载的旋钮。不同层注意力熵尺度不同，跨层直接比较排序可能引入偏差；若只在末层估计熵，开销小但可能错过高熵层的细粒度信息；若逐层估计，开销随层数线性增长。服务侧应把“熵估计层数”作为配置项并与K联合测量，因为二者共同决定TTFT净收益。可核查的口径是：固定K，改变熵估计层数，记录TTFT与ρ分桶下的对齐质量；固定层数，改变K，记录并发上限与精度边界。两组扫描交叉出的可行域，才是ERA在该服务上真正可部署的配置空间。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-13\">十三 · 负载形态如何界定 ERA 的可用边界</h3>\n<p>ERA 的收益上限由视觉 token 在端到端序列中的占比决定，因此负载形态是第一道筛子。设单请求视觉 token 数为 N_v、文本 token 数为 N_t、压缩预算为 K，则预填阶段的计算量近似按 (K+N_t)/(N_v+N_t) 缩放，而解码阶段每步仍需读取全部 KV，收益被摊薄。对以长文本输出为主的请求，视觉占比低，压缩带来的首 token 延迟改善有限；对高分辨率单图或短帧视频、文本提示极短的请求，N_v 远大于 N_t，压缩比直接决定预填延迟与 KV 占用，是 ERA 的主战场。测量口径应固定为：按请求记录 (N_v, N_t, K, 输出长度)，分别统计预填耗时与解码耗时，避免用端到端平均吞吐掩盖结构性差异。</p>\n<p>并发与批大小受压缩后 token 总数约束，而非请求数。调度器应按 Σ(K_i+N_t,i) 重算每批 KV 页需求，再定并发上限；若沿用压缩前的页表预算，会出现显存虚占、批大小被人为压低。整流在张量并行下要求全局归一化一致，即各分片对被保留集合的权重和必须跨卡归约后再除，否则分片各自归一化会破坏跨模态对齐——这是一条硬性失效条件，而非性能折衷。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{TTFT}} \\approx t_{\\text{enc}} + t_{\\text{entropy}} + t_{\\text{prefill}}(K+N_t)$$</div>\n<p>上式给出低延迟 SLO 下的关键判断：熵估计与排序开销 t_entropy 若不能融合进视觉编码器或注意力 kernel，就会与剪枝收益直接对冲。工程上应以“压缩比—额外算子延迟”二维扫描定位拐点，而非假定压缩比越高越好。视频多帧输入是另一类边界：逐帧独立按熵排序，帧间保留集合不一致会引入时序抖动，表现为批内延迟方差上升与跨帧语义断裂；此时应改为跨帧统一预算分配或对熵分数做时序平滑，并把帧间保留集合的 Jaccard 重叠率纳入监控口径。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>ERA 适用性</th><th>需监控口径</th></tr></thead><tbody><tr><td>高分辨率单图、短提示</td><td>收益显著，预填主导</td><td>N_v/K 比、TTFT 分解</td></tr><tr><td>长文本输出</td><td>解码占比高，收益摊薄</td><td>预填/解码耗时比</td></tr><tr><td>多帧视频</td><td>需跨帧预算协调</td><td>帧间保留集合重叠率、批内延迟方差</td></tr><tr><td>极低 K</td><td>整流无法补偿信息损失</td><td>整流前后注意力熵差、精度回归</td></tr></tbody></table>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-14\">十四 · 熵估计与整流在 kernel 层的落点</h3>\n<p>ERA 的计算图在推理期只有两段新增工作：视觉侧逐 token 的注意力熵估计，以及跨模态注意力层对被保留 token 的掩码重归一化。前者决定保留集合 <span>𝒦</span>，后者决定保留集合上的注意力质量如何重新分配。这两段都不改变 LLM 权重，但都必须在 GPU 上以算子形式落地，因此本部分关心的是：它们分别落在哪个 kernel 里、用什么数据类型算、累加精度够不够、以及在 Blackwell 上能否借 tcgen05 与 TMEM 把开销压进既有注意力流水线。</p>\n<p>熵估计的输入是视觉编码器某一层（或末层）的注意力分布 <span>p<sub>ij</sub></span>，即第 i 个视觉 token 对第 j 个位置的注意力权重。若该层注意力已经以 FP16/BF16 物化在片上，熵计算就是对每行做一次 <span>−Σ p log p</span> 的归约。这一步的算术强度极低：每个 token 只产生一个标量分数，却要读整行注意力。因此它的代价不在 FLOPs，而在把注意力矩阵从片上搬到可归约位置的带宽，以及 log 的超越函数开销。工程上应把它融合进注意力 epilogue——在 softmax 归一化完成后、写回共享内存之前顺手算出熵分数，而不是另起一个独立 kernel 再读一遍注意力。若另起 kernel，视觉 token 数 N<sub>v</sub> 较大时这次额外读写会直接吃掉剪枝带来的预填收益。</p>\n<p>整流段则天然属于跨模态注意力的 epilogue。给定保留掩码 <span>𝟙[i∈𝒦]</span>，整流后的权重是 <span>ã<sub>i</sub> = a<sub>i</sub>·𝟙[i∈𝒦] / Σ<sub>j∈𝒦</sub> a<sub>j</sub></span>。分母是一次跨保留集合的求和，分子是逐元素掩码乘法。这一步必须在 softmax 之后、值向量加权求和之前完成，否则被剪 token 的贡献已经混入输出，再归一化也补不回来。把它做成 epilogue 的代价是一次长度为 K 的归约加一次逐元素缩放，相对于主 MMA 可忽略；但若框架把跨模态注意力拆成多个 kernel 阶段，这次归约就会变成一次额外的全局同步，在张量并行下尤其昂贵。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-15\">十五 · 数据类型选择：从 BF16 到 NVFP4 的逐段取舍</h3>\n<p>ERA 本身不引入权重，所以它的数值精度问题不是量化模型参数，而是新增算子的中间表示。熵估计对 <span>p<sub>ij</sub></span> 的动态范围敏感：softmax 输出集中在 [0,1]，大量元素接近 0，log 后在负值区间拉开。用 FP16 表示 p 再算 log，接近 0 的元素会因次正规数下溢而丢失，导致 <span>−p log p</span> 被截断为 0，熵被系统性低估。BF16 的指数位与 FP32 相同，动态范围足够覆盖极小概率，但尾数只有 8 位，p 的相对误差在 2<sup>−8</sup> 量级，对熵这种求和型统计量尚可接受。工程判断是：熵归约的输入用 BF16 或直接保留 FP32 的 softmax 中间结果，归约累加器用 FP32。</p>\n<p>整流段的数值风险不同。分母 <span>Σ<sub>j∈𝒦</sub> a<sub>j</sub></span> 是保留集合上的权重和，若保留集合很小而注意力分散，分母可能远小于 1，逐元素除法会放大误差。这里 <span>a<sub>i</sub></span> 若已是 FP8（例如跨模态注意力在 FP8 下计算），则分母的累加必须升到 FP32 或至少 BF16，否则 K 较小时归一化结果抖动明显。Blackwell 的第五代 Tensor Core 支持 FP8 与 NVFP4 的矩阵乘，但 ERA 的整流是逐元素与归约操作，不走 MMA 通路，因此它不受 Tensor Core 数据类型约束，反而受 CUDA core 上的除法与归约精度约束。这与量化方案可以共存：LLM 主干与跨模态注意力的 QK^T、PV 走 NVFP4/FP8 MMA，整流 epilogue 在 FP32 累加器上做掩码与除法，两者不冲突。</p>\n<table class=\"mini\"><thead><tr><th>算子段</th><th>输入精度</th><th>累加/中间精度</th><th>主要误差源</th><th>系统代价</th></tr></thead><tbody><tr><td>熵估计归约</td><td>BF16 / FP32 softmax 输出</td><td>FP32</td><td>近零概率的 log 下溢</td><td>注意力行带宽、log 超越函数</td></tr><tr><td>TopK 选择</td><td>FP32 熵分数</td><td>—</td><td>跨层熵尺度不可比</td><td>N<sub>v</sub> 长度排序，延迟随 N<sub>v</sub> 增长</td></tr><tr><td>整流掩码乘</td><td>FP8/BF16 注意力权重</td><td>FP32 分母</td><td>小 K 下分母过小放大误差</td><td>K 长度归约 + 逐元素除法</td></tr><tr><td>PV 加权求和</td><td>NVFP4/FP8</td><td>FP32</td><td>低精度值向量累积</td><td>MMA 吞吐，受 TMEM 容量约束</td></tr></tbody></table>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-16\">十六 · 累加精度与误差传播：熵排序为何不能跨层直接比</h3>\n<p>熵分数 <span>𝒮<sub>i</sub> = −Σ<sub>j</sub> p<sub>ij</sub> log p<sub>ij</sub></span> 是一个绝对量，其量纲随注意力分布的弥散程度变化。不同层的注意力熵尺度不同：浅层注意力分散、熵值高，深层注意力集中、熵值低。若把各层熵分数放进同一个 TopK 排序池，深层 token 会系统性排在后面而被误剪。这不是浮点误差，而是度量本身的层间不可比性。工程上有两种处理：一是只在固定层（如视觉编码器末层或跨模态第一层）取熵，避免跨层混合；二是对每层熵做层内归一化后再比较。前者实现简单、排序开销只发生一次；后者需要维护每层的均值与方差，增加一次归约但不增加排序长度。</p>\n<p>累加精度对排序稳定性的影响体现在并列与近并列情形。TopK 的边界处，两个 token 的熵分数若相差在 FP32 累加的舍入误差内，排序结果对批内不同请求可能抖动，导致同一图像在不同批中保留不同 token，破坏批间一致性。这在连续批处理下会被放大：调度器把不同请求拼进同一批，若每个请求的保留集合不稳定，KV cache 页表与显存预算的复用率下降。缓解手段是把熵分数在 FP32 下算完后做一次确定性的 tie-break（例如按 token 索引），使排序在数值上可复现。</p>\n<div class=\"formula\">$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}},\\qquad \\sum_{i\\in\\mathcal{K}}\\tilde{a}_{i}=1$$</div>\n<p>逐项解释：分子 <span>a<sub>i</sub>·𝟙[i∈𝒦]</span> 把被剪 token 的权重清零，保留 token 的权重原样保留；分母是保留集合上的权重和，起重新归一化作用；等式右端说明整流后保留集合上的权重构成一个合法分布，注意力质量不再泄漏到已删除位置。代价在于分母的求和在张量并行下是跨 rank 的归约：若视觉 token 沿序列维切分到多个 rank，每个 rank 只持有部分保留 token 的权重，必须做一次 all-reduce 才能得到全局分母，否则各 rank 用局部和归一化，结果不一致，跨模态对齐被破坏。这次 all-reduce 的长度是 1（标量），延迟由通信启动开销主导，在 NVLink 5 域内可接受，但每层每次注意力都做一次会累积成可观开销，因此应把整流归约与已有的注意力行归约合并。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变代价结构</h3>\n<p>Blackwell 的 tcgen05 指令把矩阵乘的累加器放在 TMEM（Tensor Memory）而非寄存器堆，第五代 Tensor Core 通过 2-SM MMA 让两个 SM 协同完成一次更大的 MMA，共享操作数与累加器。对 ERA 而言，这些特性的意义不在熵估计（它是归约，不走 MMA），而在整流之后的 PV 加权求和：保留集合从 N<sub>v</sub> 缩到 K 后，PV 的 M 维变小，若仍按原 tile 尺寸发射 MMA，会出现大量空转。2-SM MMA 允许把两个 SM 的算力合并到一次更大的 K 维归约上，在 K 较小时反而能提高单次 MMA 的有效利用率；代价是跨 SM 的操作数分发与 TMEM 分配，需要 CUTLASS 层面的 tile 调度配合，不能由框架自动完成。</p>\n<p>TMEM 的容量约束直接影响批调度。TMEM 是片上张量内存，容量有限，累加器占用随并发 MMA 数量增长。当批内请求数上升、每个请求的保留集合 K 不同，跨模态注意力的 MMA 形状在批内不一致，框架往往按最大 K 补齐，造成 TMEM 与算力浪费。ERA 的压缩比越高（K 越小），这种形状不一致的相对代价越大。工程判断是：在服务侧按 K 分桶（把 K 接近的请求拼批），使 MMA 形状在批内一致，从而让 tcgen05 的 tile 调度与 TMEM 分配可复用。这与连续批处理的调度器耦合，属于 ERA 部署时必须改的调度策略，而非 kernel 内部优化。</p>\n<p>另一个代价点是熵估计与主 MMA 的资源竞争。熵归约走 CUDA core 与共享内存，主注意力走 Tensor Core 与 TMEM，两者若在同一 kernel 内融合，需要划分 warp 角色（部分 warp 做 MMA，部分做归约），否则归约的同步会阻塞 MMA 流水。融合得好，熵估计的边际开销接近于零；融合不好，它变成一次独立的全局内存往返，在 N<sub>v</sub> 大、K 小的配置下可能抵消全部预填收益。这是 ERA 在 Blackwell 上能否兑现加速的核心工程变量，材料未给出实测数据，只能从机制上判断其取决于 kernel 融合程度。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-18\">十八 · 一个具体例子：单帧图像请求的算子时序</h3>\n<p>设一次请求送入一张图像，视觉编码器输出 N<sub>v</sub> 个视觉 token，服务侧配置预算 K（K &lt; N<sub>v</sub>）。时序如下：视觉编码器末层注意力在 epilogue 中顺带算出每个 token 的熵分数，写入一块长度为 N<sub>v</sub> 的 FP32 缓冲；随后一个轻量排序 kernel 取熵最高的 K 个索引，输出保留掩码。排序的延迟随 N<sub>v</sub> 增长，是纯延迟项、不随批增大而摊薄，因此在视频多帧输入下 N<sub>v</sub> 成倍增长时，排序会成为不可忽视的固定开销。缓解方式是把排序下推到更小的候选集：先按粗粒度分块求块内最大熵，再在候选块内精排，把排序长度从 N<sub>v</sub> 降到 N<sub>v</sub>/b。</p>\n<p>进入 LLM 后，跨模态注意力对视觉侧做 QK<sup>T</sup>，得到权重 <span>a<sub>i</sub></span>；epilogue 读入保留掩码，清零被剪位置，在 FP32 下求保留集合的和作为分母，逐元素相除得到 <span>ã<sub>i</sub></span>；随后 PV 加权求和，值向量按 NVFP4/FP8 存储，累加在 FP32。整流后的序列长度从 N<sub>v</sub> 降到 K，写入分页 KV cache 的页数随之减少，调度器按新的每请求显存占用重算并发批大小。解码阶段每步只读 KV cache，不再触碰视觉 token 的熵与整流逻辑，因此 ERA 的收益集中在预填，解码阶段收益有限——这与视觉 token 在总序列中的占比直接相关，占比越高，端到端加速越明显。</p>\n<p>显存侧的账要分开算：KV cache 占用按 K 而非 N<sub>v</sub> 计，节省量与压缩比同阶；但熵分数缓冲、保留掩码、排序中间结果都是额外分配，虽小却按请求常驻，在极高并发下会挤占本已紧张的显存预算。带宽侧的账则是：熵估计多读一遍注意力行，整流多一次标量 all-reduce，两者都是小量但非零。功耗侧，熵归约的超越函数与排序的比较操作走 CUDA core，能效低于 Tensor Core 的 MMA，若这部分占比上升，整卡能效会被拉低。因此 ERA 的工程判断应落在“压缩比是否足够大，使预填节省超过新增算子的固定开销”这一条上，而不是笼统地说它降低显存。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-19\">十九 · 熵估计与整流 kernel 的融合边界：精度、显存与低延迟 SLO 下的失效条件</h3>\n\n<p>ERA 的算子代价集中在两处：熵估计与整流归一化。熵估计要在视觉侧对每个 token 的注意力分布做一次 <span>−∑p log p</span> 归约，再对 N_v 个分数排序取 TopK；整流则是在跨模态注意力 softmax 之后插入一次掩码乘与保留位置求和除法。两者若各自作为独立 kernel 下发，中间张量要往返 HBM：以 BF16 存储的注意力分数矩阵规模为 <span>N_v × d</span>，熵归约的读写带宽代价与一次完整 attention score 写回同量级，在 B200 上这足以把预填阶段省下的时间吃掉相当一部分。真正的工程判断是：熵估计必须融进视觉编码器最后一个 attention 的 epilogue，整流必须融进跨模态 attention 的 softmax epilogue，否则 ERA 只是把计算从预填搬到了额外算子。\n\n<div class=\"formula\">$$\\tilde{a}_i=\\frac{a_i\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_j},\\qquad \\text{err}=\\left\\|\\tilde{a}-a^{\\ast}\\right\\|_1\\ \\text{随}\\ \\frac{N_v-K}{N_v}\\ \\text{单调上升}$$</div>\n\n公式第一项是整流本身：分子做掩码、分母只在保留集合上求和，等价于把被剪位置的注意力质量按比例摊回保留 token。第二项是它的失效边界——整流只能重分配质量，不能创造信息；被剪 token 承载的细粒度语义在 <span>a*</span> 中已经不存在，L1 偏差随压缩比上升而单调增大。这意味着极低 K 下“整流保证对齐”是不成立的，精度塌陷是结构性的而非数值性的。</p>\n\n<p>数值精度层面有三条硬约束。其一，熵计算对 log 的数值稳定性敏感：FP16 下 <span>p</span> 接近 0 时 <span>p log p</span> 易下溢为 0，熵被系统性低估，导致本应保留的高熵 token 被误判为冗余；用 BF16 做累加、FP32 做 log 与归约是可行折中，代价是归约路径上的寄存器压力与一次精度提升的类型转换。其二，整流的分母求和必须在 FP32 累加下完成，若沿用 FP16 累加，保留集合较大时求和误差会直接改变归一化系数，跨模态注意力整体偏移。其三，若主干已切到 NVFP4/FP8，视觉侧注意力分数处于低精度，熵估计的输入本身已被量化噪声污染，此时熵排序的稳定性需要在量化前后做一致性校验——这是 ERA 与低精度量化叠加时最容易被忽略的耦合点。\n\n<table class=\"mini\"><thead><tr><th>环节</th><th>精度要求</th><th>系统代价</th></tr></thead><tbody><tr><td>熵归约</td><td>log 用 FP32，累加 FP32</td><td>寄存器压力上升，占用 tcgen05 的 TMEM 预算</td></tr><tr><td>TopK 排序</td><td>分数 BF16 足够</td><td>N_v 规模排序的延迟随分辨率线性增长</td></tr><tr><td>整流归一化</td><td>分母 FP32 全局求和</td><td>张量并行下需跨分片 all-reduce，破坏 kernel 融合</td></tr></tbody></table>\n\n整流在张量并行下的全局求和是第二个失效条件：跨模态注意力按头或按序列切分到多卡时，分母 <span>∑_{j∈K}a_j</span> 是全局量，各分片若各自归一化，结果不一致会直接破坏跨模态对齐，而做一次 all-reduce 又引入通信延迟，与 NVLink 5 上的集合通信预算争夺带宽。可行的工程折中是让整流在单卡内完成、按头切分而非按序列切分，把归一化保持在本地。第三个失效条件是视频多帧：逐帧独立算熵再排序，帧间熵尺度不同，剪枝后帧间 token 预算分配不均，批内延迟方差被放大；服务侧应以请求为单位而非以帧为单位做预算分配。最后，在低延迟 SLO 下，熵估计与排序的固定开销与 K 无关，当视觉 token 占比本就不高时，这笔开销无法被预填收益摊薄，ERA 应关闭——这是容量规划中必须显式建模的开关阈值，而不是默认开启的插件。</p>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-20\">二十 · 显存账本的三层结构与可复算预算</h3>\n<p>在 Blackwell 上给一个 MLLM 请求做显存预算，必须先把它拆成三本账：权重、激活、KV cache。三者性质不同——权重是静态的、按模型并行切分后每卡一份；激活是随批内序列长度与算子实现浮动的瞬态量；KV cache 则是随请求生命周期增长的持久量，也是连续批处理真正被卡住的地方。ERA 的介入点只在第三本账的输入端：视觉 token 从 N_v 压到 K，直接改变写入 KV cache 的序列长度。</p>\n<p>可复算的预算形式如下。设单卡 HBM 容量为 C（B200/B300 的 HBM3e 容量按整卡规格折算到每卡可用额度，需扣除框架预留与通信缓冲），权重占用 W、激活峰值 A、每 token 每层 KV 字节数为 b_kv，层数 L，则单请求 KV 占用与最大并发请求数分别为：</p>\n<div class=\"formula\">$$M_{\\text{kv}} = 2 \\cdot L \\cdot b_{\\text{kv}} \\cdot (K + T_{\\text{txt}}),\\qquad N_{\\max} = \\left\\lfloor \\frac{C - W - A}{M_{\\text{kv}} \\cdot \\alpha} \\right\\rfloor$$</div>\n<p>其中 2 表示 K 与 V 两份，T_txt 为文本侧 token 数，α 为分页碎片与预留系数（大于 1，用于吸收页表、对齐与临时缓冲）。这个式子的工程含义很直接：N_max 对 K 的敏感度取决于 K 与 T_txt 的相对大小。图像输入下 K 往往远大于 T_txt，压缩视觉 token 几乎线性放大并发；长文本对话下 T_txt 占主导，ERA 的并发收益被稀释。这就是“端到端加速取决于视觉 token 占比”在显存账本上的具体形态。</p>\n<p>举例：一个以视觉为主的请求，原始 N_v 远大于 K，压缩后 KV 占用按比例下降，调度器在同一张卡上能塞进更多请求；而一个文本占九成的请求，即使 K 减半，M_kv 的下降幅度也很有限。做容量规划时必须按负载混合比例加权，而不是拿单条视觉请求的压缩比去外推集群吞吐。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-21\">二十一 · 分页 KV cache 与压缩后序列长度的耦合</h3>\n<p>分页 KV cache 把逻辑序列切成固定大小的页，页表把逻辑位置映射到物理块。它解决的是碎片与变长问题，但也引入一个 ERA 特有的耦合：压缩发生在预填之前还是之中，决定了页表要怎么写。若熵估计与 top-k 保留在视觉编码器输出后一次完成，则写入 KV 的序列从一开始就是长度 K，页表按 K 分配，逻辑位置连续，最干净。若整流需要跨模态注意力层参与、压缩分散在多层进行，则逻辑位置会出现“被剪除的空洞”，页表必须支持稀疏逻辑索引，或者干脆在压缩完成后重排一次逻辑位置映射。</p>\n<p>伪代码层面的判断：</p>\n<ul>\n<li>路径 A（前置压缩）：视觉 token → 熵分数 → top-k → 整流准备 → 拼接文本 → 预填写 KV。页表长度 = K + T_txt，无空洞，碎片率最低。</li>\n<li>路径 B（层内压缩）：每层注意力前做掩码与重归一化，KV 仍按 N_v 写入但标记无效位。页表需要 valid 位图，物理块利用率下降，等于把省下的容量又吐回去一部分。</li>\n</ul>\n<p>代价对比是明确的：路径 B 的显存节省被无效页抵消，且整流在张量并行切分下要求全局求和一致，跨卡归约会引入额外通信与同步点，落在预填关键路径上就是首 token 延迟。路径 A 把压缩成本前移到视觉编码器之后的一次排序，排序开销是 O(N_v log N_v) 的轻量操作，但熵估计本身是额外前向——这部分算力若不能融进视觉编码器 kernel，就会以固定延迟的形式加在预填之前，低延迟 SLO 下这是主要风险点。</p>\n<p>工程判断：优先选路径 A，把整流实现为对已保留集合的注意力掩码加归一化，使 KV 写入侧完全看不到被剪 token。这样分页器、前缀复用、页表回收逻辑都不需要改动，ERA 才真正是“插件”。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-22\">二十二 · 带宽瓶颈的位置：预填是算力，解码是带宽</h3>\n<p>Blackwell 上 MLLM 推理的带宽瓶颈要分阶段看。预填阶段是大矩阵乘，算术强度高，瓶颈在 tensor core 吞吐与 tcgen05/TMEM 的数据搬运效率；解码阶段每步只处理一个 token，权重要被完整读一遍，瓶颈落在 HBM3e 带宽上。ERA 压缩视觉 token 主要削减的是预填阶段的计算量与 KV 写入量，对解码阶段的每步带宽需求影响很小——因为解码时读的是权重，不是视觉 token。这解释了为什么“解码阶段收益有限”。</p>\n<p>但 KV cache 的读带宽在解码时并非零：注意力要对历史 KV 做读取，序列越长，每步读取的 KV 字节越多。压缩后 K 变小，解码每步的 KV 读取量下降，长上下文、大并发下这部分收益会显现。定量地，解码单步 KV 读取字节约为 2·L·b_kv·(K+T_txt)·B（B 为批内活跃序列数），它与权重读取字节同量级时，KV 带宽就成为不可忽略的第二瓶颈。因此在视觉 token 占比高、批又大的配置下，ERA 的收益不止于预填。</p>\n<p>具体例子：视频输入下请求内帧数多，N_v 极大，预填阶段被视觉 token 拖成秒级；压缩后预填计算量按 K/N_v 下降，同时 KV 写入与后续解码读取同步下降。反之，单图短问答请求的 N_v 有限，压缩收益主要体现在并发数上而非单请求延迟。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-23\">二十三 · 复用、压缩、卸载：三条省显存的路怎么排优先级</h3>\n<p>面对显存不足，工程上有三条路：复用（前缀缓存、跨请求共享视觉 KV）、压缩（量化 KV、低秩、token 剪枝）、卸载（把冷 KV 换到主机内存或远端）。它们的代价结构完全不同，排序应按“是否落在关键路径”来定。</p>\n<table class=\"mini\"><thead><tr><th>手段</th><th>机制</th><th>主要代价</th><th>与 ERA 的关系</th></tr></thead><tbody>\n<tr><td>前缀复用</td><td>相同图像/系统提示的 KV 块跨请求共享，页表指向同一物理块</td><td>命中率依赖负载重复度；失效判定与回收逻辑复杂</td><td>压缩后 K 变小，单块更省，但复用收益被稀释；需保证整流后的 KV 与复用块语义一致</td></tr>\n<tr><td>KV 量化</td><td>KV 以 FP8/NVFP4 存储，读取时反量化</td><td>反量化算力与精度损失；与注意力 kernel 融合程度决定净收益</td><td>与 ERA 正交，可叠加；压缩比越高，量化误差对对齐的影响越需评估</td></tr>\n<tr><td>Token 剪枝</td><td>ERA 的熵引导 top-k 与整流</td><td>熵估计前向开销；极低预算下信息不可恢复</td><td>本部分主题，作用于 KV 写入前的序列长度</td></tr>\n<tr><td>卸载</td><td>冷 KV 页换出到主机内存，按需换入</td><td>PCIe/C2C 往返延迟，换入发生在解码关键路径上</td><td>压缩后 KV 总量下降，卸载触发频率降低，是间接收益</td></tr>\n</tbody></table>\n<p>优先级判断：复用优先于压缩，压缩优先于卸载。复用不损失信息，只在命中率上打折；压缩有精度代价但可预测；卸载把延迟不确定性引入解码路径，是最后手段。ERA 属于压缩一档，它的价值在于把压缩做在写入前，使后续三条路都工作在更小的基数上——卸载阈值更容易满足，复用块的粒度更细，量化误差影响的元素更少。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-24\">二十四 · HBM3e 容量怎么算，以及整流在并行切分下的显存一致性</h3>\n<p>容量计算不是把标称容量直接除以模型大小。要扣除：框架与运行时预留、通信缓冲（NVLink 5 集合通信的暂存区）、页表与元数据、激活峰值、以及为突发批预留的余量。设标称容量为 C_nom，则可用额度 C = C_nom − R_fw − R_comm − R_meta，其中 R_meta 随页大小与最大并发线性增长，页越小碎片越少但元数据越多，存在一个使总占用最小的页大小，需按实际序列长度分布实测选定。</p>\n<p>整流在张量并行下的显存一致性是个容易被忽略的点。整流公式要求对保留集合的注意力权重做全局归一化，若注意力头被切到不同卡上，各分片的局部和必须跨卡归约后才能得到全局分母。归约本身不占多少显存，但它要求各分片在同一同步点持有中间结果，等于在预填关键路径上增加一个屏障。若把整流改为“每分片独立归一化”，数值上不等价，跨模态对齐会被破坏——这正是失败模式里“分片归一化不一致”的具体机制。</p>\n<p>可复算的例子：给定 L、b_kv、K、T_txt 与 α，先算单请求 M_kv，再用 C 减去 W 与 A 得到可用池，除以 M_kv·α 得 N_max。把 K 减半重算一遍，得到并发提升倍数；再把 T_txt 放大到主导量级重算，观察提升倍数如何衰减。这个两步复算就能判断某条负载上 ERA 的容量收益是否值得部署熵估计算子。</p>\n<p>最后落在工程判断上：ERA 的显存收益是确定的（K 直接进 M_kv 公式），但净收益取决于熵估计与整流能否融进现有 kernel 而不引入额外屏障与无效页。部署前应先用上述预算式在目标负载混合上算出 N_max 的提升，再对照熵估计的固定延迟开销，若前者带来的吞吐增益不能覆盖后者在首 token 延迟上的损失，就应把压缩路径改为前置一次性排序、整流退化为写入前掩码，把复杂度从关键路径上挪走。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-25\">二十五 · 显存账本与带宽拐点：ERA 压缩后 KV 预算的可复算边界</h3>\n<p>ERA 把视觉 token 从 N_v 压到 K，账本上最先变化的是 KV cache 而非权重。以分页 KV 为例，每请求视觉侧 KV 字节数为 <span class=\"formula\">$$M_{\\text{kv}} = 2 \\cdot L \\cdot K \\cdot d_h \\cdot H_{\\text{kv}} \\cdot b_{\\text{kv}}$$</span>，其中 2 为 K/V 两份，L 为层数，d_h 为头维，H_kv 为 KV 头数，b_kv 为每元素字节数（FP8 取 1、NVFP4 取 0.5）。压缩比 ρ=N_v/K 直接线性缩放该项，而权重与激活不随 ρ 变化——这意味着 ERA 的显存收益存在上限：当视觉 KV 只占单请求总占用的一小部分时，提高并发带来的吞吐增益会被权重常驻与文本侧 KV 稀释。工程判断应先量出视觉 KV 占比，再决定是否值得为熵估计付出额外前向。</p>\n<p>带宽瓶颈的位置随批形态迁移。预填阶段视觉 token 的 QKV 投影与注意力是算力主导，压缩后预填延迟近似按 ρ 下降；解码阶段每步只读全部 KV，此时带宽主导，读放大为 <span class=\"formula\">$$B_{\\text{step}} \\approx M_{\\text{kv}} \\cdot \\frac{T_{\\text{out}}}{t_{\\text{step}}}$$</span>，K 减小使每步 KV 读取线性下降，但解码收益取决于视觉 KV 在总 KV 中的份额——长文本上下文下该份额被稀释，ERA 对 TPOT 的改善有限。HBM3e 容量核算应按“权重 + 峰值激活 + 批内 KV 页池 + 碎片余量”四项求和，其中 KV 页池按压缩后 K 重算页数，页表项数与碎片随 K 减小而下降，这是分页策略与 ERA 叠加时的隐性收益。</p>\n<p>失效条件集中在三处。其一，熵估计若不能融合进视觉编码器或跨模态注意力 kernel，额外算子延迟在低延迟 SLO 下会吃掉预填收益，尤其当 ρ 不大时净收益可能为负；其二，张量并行下整流归一化的分母必须跨分片全局求和，各分片独立归一化会破坏跨模态对齐，需在 all-reduce 后统一重标定；其三，极低 K 时整流只能重分配注意力，被剪除的细粒度信息不可恢复，精度随压缩比上升而塌陷，材料未给出该边界数值，部署应以精度回归曲线而非固定 K 作为准入条件。视频多帧场景下逐帧独立剪枝还会引入帧间熵排序不一致，批内延迟方差随之放大。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随 K 的变化</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉 KV 页池</td><td>线性 ∝ K</td><td>并发上限提升，页表项减少</td></tr><tr><td>权重常驻</td><td>不变</td><td>压缩收益被稀释</td></tr><tr><td>熵估计算子</td><td>与 N_v 相关</td><td>未融合则延迟净增</td></tr><tr><td>整流归一化</td><td>与 K 相关</td><td>TP 下需全局求和</td></tr></tbody></table>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-26\">二十六 · 压缩后序列进入调度器的那一步</h3>\n<p>ERA 把视觉 token 从 N_v 压到 K，这件事在调度器眼里不是“模型变快了”，而是“每个请求的预填长度分布变了”。连续批处理（continuous batching）的核心循环按迭代粒度重组批：每个 decode step 结束后，完成的请求退出、排队的请求插入，批内序列长度随时变化。视觉 token 压缩直接改变的是插入时刻的代价——一个带图请求进入批时，它的预填长度从 N_v+L_text 降到 K+L_text，于是调度器可以在同一个显存预算下多塞几个请求。代价在于：批内序列长度方差变大。文本请求长度分布相对平滑，而图像/视频请求经熵引导剪枝后长度由预算 K 决定，K 是服务侧配置量而非输入自然长度，于是批内出现“长文本请求 + 短视觉请求”的混合形态，注意力 kernel 的 tile 利用率与负载均衡需要重新评估。</p>\n<p>具体机制上，调度器必须在请求准入时就知道该请求压缩后的 KV 占用，而不是等视觉编码器跑完才知道。工程做法是把熵估计与 top-k 选择前移到准入路径的预估阶段：用视觉编码器输出的 token 数与配置的 K 直接算出预留页数，写入分页 KV cache 的页表预留，再让预填真正执行。伪代码思路是：</p>\n<div class=\"formula\">$$\\text{reserve}(r)=\\left\\lceil \\frac{K_r + L^{text}_r}{P}\\right\\rceil,\\quad \\text{admit}(r)\\ \\text{iff}\\ \\sum_{r\\in B}\\text{reserve}(r)\\le \\text{free pages}$$</div>\n<p>其中 P 为分页大小。这里的关键判断是：K 是预算而不是实测值，所以预留是保守的；若整流后实际保留数少于 K，页表可回收差额，但回收动作本身有同步开销。对首 token 延迟（TTFT）敏感的 SLO，预留保守一点换确定性，比动态回收换显存利用率更划算。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-27\">二十七 · chunked prefill 与熵估计的算子位置</h3>\n<p>chunked prefill 把长预填切成若干块，与 decode 迭代交错执行，目的是压住 decode 的迭代间隔（ITL）不被长预填拖爆。ERA 的熵估计是一次额外前向，它必须被放进 chunk 的哪一段，决定了这套方案能否在低延迟 SLO 下成立。若熵估计在视觉编码器输出后一次性完成，那么第一个 chunk 就要承担全部 N_v 个 token 的熵计算与排序，形成尖峰；若把熵估计按视觉 token 分块、与预填 chunk 对齐，则排序需要跨 chunk 的全局归并，top-k 的 K 个保留位在最后一块才知道，整流只能在跨模态注意力首次执行前插入一次全局重排。</p>\n<p>代价结构很清楚：熵估计的算力开销与 N_v 成正比，而它带来的收益是后续 K 个 token 的预填与 KV 写入。设单 token 预填代价为 c_p、熵估计单 token 代价为 c_e，则只有当 K·c_p 的节省超过 N_v·c_e 的额外开销时，端到端 TTFT 才下降。这个不等式在视觉 token 占比高的请求上容易满足，在“一张小图 + 极长文本”的请求上则不成立——此时 N_v 小、K 更小，熵估计的相对开销被文本预填稀释，收益趋近于零。工程判断是：按 N_v/(N_v+L_text) 设阈值，低于阈值直接跳过熵引导路径走原始注意力排序，避免为小图付排序税。</p>\n<p>另一个机制细节是排序本身。top-k 在 N_v 上做全排序是 O(N_v log N_v)，在 B200 上可以用 warp 级基数选择降到近似线性；但若熵分数需要跨张量并行分片归并，则要引入一次 all-reduce 或分片局部 top-k 再归并，通信量与分片数成正比。这属于并行与通信范畴的问题，此处只指出它对 chunk 边界的影响：归并点必须落在 chunk 边界上，否则 chunk 内无法确定哪些 token 进入整流后的注意力集合。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-28\">二十八 · 优先级、抢占与整流的一致性约束</h3>\n<p>多模态服务里请求优先级差异明显：交互式对话的 TTFT 敏感，批量图像理解的吞吐敏感，视频流请求则有持续到达的节拍。抢占（preemption）在显存不足时把低优先级请求的 KV 换出或重算。ERA 在这里引入一个不常见的约束：整流是对被保留 token 集合的归一化，一旦请求被抢占并重算，保留集合必须可复现，否则重算后的注意力归一化与首次执行不一致，输出漂移。熵分数由前向计算得出，理论上确定性，但若熵估计依赖的中间张量在换出时被丢弃，重算就要重新跑一遍熵估计——这是抢占代价的隐藏项。</p>\n<p>工程做法是把保留集合的索引（K 个 token 的位置）随 KV 页一起持久化，作为请求状态的一部分，而不是每次重算重新排序。这样抢占恢复时只需按索引重建整流掩码，不必重跑熵估计。代价是每个请求多存 K 个整型索引，相对 KV 页本身可忽略，但索引与页表的同步更新要在调度器与注意力 kernel 之间建立契约。表格对比三种策略在尾延迟上的取向：</p>\n<table class=\"mini\"><thead><tr><th>策略</th><th>TTFT 影响</th><th>ITL 影响</th><th>显存代价</th></tr></thead><tbody><tr><td>不抢占，排队等待</td><td>高优先级请求被拖长</td><td>稳定</td><td>低</td></tr><tr><td>换出 KV 页</td><td>恢复时重载页</td><td>恢复迭代出现尖峰</td><td>中（需换出缓冲）</td></tr><tr><td>丢弃并重算</td><td>重跑预填与熵估计</td><td>恢复迭代长尾</td><td>低，但算力重复</td></tr></tbody></table>\n<p>尾延迟的来源往往不是平均吞吐，而是抢占恢复的那几个迭代。把保留索引持久化，等于把“重算”降级为“重放”，这是压尾延迟最直接的一刀。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-29\">二十九 · 分离式预填/解码下的视觉侧归属</h3>\n<p>分离式（disaggregated）预填/解码把预填节点与解码节点分开部署，KV 通过 NVLink 5 或 NIXL 在节点间搬运。ERA 的视觉 token 压缩天然属于预填侧：熵估计、top-k、整流掩码构造都在预填节点完成，传给解码节点的是压缩后的 KV 与保留索引。这带来两个调度收益。其一，预填节点的算力需求随 K 下降，视觉编码器与 LLM 预填可以按压缩后的负载重新配比；其二，KV 传输量从 N_v 降到 K，跨节点带宽压力下降，GB200 NVL72 机架内的 KV 搬运时延随之缩短。</p>\n<p>代价出现在整流掩码的跨节点传递。整流公式要求对保留位置权重求和再归一化，这个求和发生在解码节点的跨模态注意力层，而掩码由预填节点生成。若掩码以位图形式随 KV 一起传输，解码节点需在每次注意力计算时应用掩码并重归一化，等于把整流开销从预填侧搬到了解码侧——而解码侧是延迟最敏感的一段。更优的做法是在预填侧就把整流后的注意力权重分布固化为 KV 的附加通道，解码侧只做标准注意力；但这要求预填侧知道解码侧每一层的注意力形态，耦合度上升。工程判断：整流若不能融合进解码侧的注意力 kernel 作为掩码乘加，就不应跨节点拆分，宁可让整流留在预填侧做一次性重排。</p>\n<p>分离式部署还改变尾延迟的统计口径。预填与解码解耦后，TTFT 由预填队列深度决定，ITL 由解码批的迭代间隔决定，两者的长尾不再耦合。视觉 token 压缩主要压 TTFT 的分布右尾——那些高分辨率、多帧的请求正是右尾的主要贡献者。视频请求的帧间熵分布不均，逐帧独立剪枝会让同一请求内不同帧的 K 不同，预填 chunk 的长度在请求内部就不均匀，chunk 边界与帧边界不对齐时，调度器需要按帧而非按请求切 chunk，否则单帧的尖峰会污染整请求的 TTFT。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-30\">三十 · 吞吐与尾延迟的取舍落在 K 上</h3>\n<p>把上面几条收束到一个旋钮：token 预算 K。K 越小，单请求 KV 占用越低，批并发越高，吞吐上升；但整流在极低 K 下只能重分配注意力、无法恢复被剪除的细粒度信息，精度随压缩比上升而下降，且熵估计的相对开销占比上升。吞吐与尾延迟的取舍不是单调的：K 降低带来的并发提升在批已饱和时不再转化为吞吐，反而因每请求算力下降导致单请求延迟分布变宽，尾延迟恶化。容量规划上应把 K 作为按请求类型分档的配置——交互式小图用较大 K 保 TTFT 稳定，批量高分辨率图用较小 K 换吞吐，视频流用帧级 K 并锁定帧边界对齐。</p>\n<p>监控指标要能区分“压缩带来的收益”与“调度带来的收益”：视觉 token 压缩比、整流前后注意力熵、TTFT 分位数、批内序列长度方差、抢占恢复迭代占比。其中批内长度方差是 ERA 特有的信号——它直接反映 K 配置与文本长度分布的匹配程度，方差抬升往往先于尾延迟恶化出现。最后落在具体机制上：整流掩码与保留索引必须作为请求状态与 KV 页同生命周期管理，熵估计必须与 chunk 边界对齐，K 必须按请求类型分档而非全局单一值；这三条不做，ERA 的压缩收益会在调度层被额外算子与重算开销吃掉。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-31\">三十一 · 当 ERA 进入连续批处理：预算、抢占与整流归一化的分片一致性</h3>\n\n<p>把 ERA 当作“请求内的预处理插件”是低估了它。在连续批处理下，token 预算 K 是一个跨请求共享的资源：调度器每步都要把新到达请求的视觉 token 数、在跑请求的剩余解码步数、分页 KV cache 的空闲页数放进同一个决策。ERA 压缩后序列从 N_v 降到 K，预填计算量与 KV 占用同步下降，但这只对“视觉 token 占比高”的请求有效；对文本主导的请求，压缩比接近 1，收益被熵估计的额外前向吃掉。因此调度侧应把 ERA 的收益写成可判定的准入条件，而非全局开关。设请求 i 的视觉 token 占比 ρ_i = N_v/(N_v+N_t)，压缩比 γ_i = K/N_v，则其预填工作量近似按 ρ_i(1−γ_i) 缩减，而熵估计开销按 N_v 线性增长。准入判据可写成：仅当 ρ_i(1−γ_i)·C_pre > c_ent·N_v 时才启用 ERA，其中 C_pre 是单位 token 预填代价、c_ent 是单位 token 熵估计代价。这个不等式在长视频、高分辨率图像上成立，在短文本配小图上不成立——这是 ERA 在批调度中的第一个边界。</p>\n\n<p>抢占策略要改。传统连续批处理按“剩余解码 token 数”或“已等待时长”决定抢占谁，但在 ERA 场景下，被抢占请求的视觉 token 已经剪枝并整流，KV cache 里存的是压缩后的 K 个位置；若抢占后重新调度，不能简单回退到原始 N_v 序列重算，否则熵排序与整流结果作废、预填白做。工程上应把 ERA 的剪枝决策（保留索引集合与整流后的归一化因子）随请求状态一起持久化，抢占恢复时直接复用压缩序列与页表映射，只重跑未完成部分的解码。代价是每个请求多存一份 K 长度的索引位图与每层整流分母，显存开销约为 K·L·4 字节量级（L 为跨模态注意力层数），相对 KV cache 本身很小，但页表管理复杂度上升：压缩后序列长度变化必须同步更新分页映射，否则解码阶段会读到已释放页。</p>\n\n<p>整流公式在张量并行下有一个容易被忽略的失效点。$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}}$$ 分母是对保留集合的全局求和。当跨模态注意力按头或按序列切分到多个 rank 时，每个 rank 只持有部分 a_j，若各自做局部归一化，各分片的分母不同，拼接后注意力质量不守恒，跨模态对齐被破坏——这与剪枝误删的后果同源，只是从“删错 token”变成“归一化错位”。正确做法是在整流前对保留集合的权重做一次 all-reduce 求全局分母，或利用 tcgen05 的 TMEM 归约能力在片上完成跨分片求和再广播。前者引入一次通信，后者依赖 kernel 融合程度。无论哪条路径，整流都不能作为独立算子挂在注意力之后，否则每次前向多一次同步，在 NVLink 5 域内尚可接受，跨节点张量并行时尾延迟会被这次归约拉长。</p>\n\n<p>尾延迟的真正来源不是平均压缩比，而是批内压缩比的方差。视频多帧输入下各帧熵分布不均，逐帧独立剪枝使同一请求内不同帧保留的 token 数波动，批内各请求的预填步数因此不同步，调度器被迫按最慢请求对齐，形成长尾。缓解手段有二：其一，把 K 从“每请求固定”改为“每请求按帧数分摊”，对帧间熵方差大的请求保留更多预算，牺牲平均吞吐换尾延迟稳定；其二，在 chunked prefill 中把视觉 token 的熵估计与剪枝放进第一个 chunk，后续 chunk 只做文本与已压缩视觉 token 的混合预填，使压缩决策尽早固化、批内步数可预测。这两种手段都以吞吐为代价：前者降低平均并发，后者要求 chunk 边界与视觉编码器输出对齐，增加了流水线气泡。ERA 的材料未给出时序一致性与批内延迟方差的实测数据，因此上述取舍只能作为部署时的保守配置，而非可承诺的 SLO 保证。</p>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-32\">三十二 · 并行切分的四个维度与视觉 token 的位置</h3>\n<p>在 Blackwell 上部署 ERA 这类推理期视觉 token 插件，第一件要决定的事不是剪多少 token，而是把视觉编码器与 LLM 分别放在哪条并行轴上。TP（张量并行）切的是单层内的权重矩阵与注意力头，EP（专家并行）切的是 MoE 层的专家集合，PP（流水并行）切的是层段，DP（数据并行）切的是请求副本。对 ERA 而言，关键约束是：熵估计发生在视觉编码器输出侧，整流发生在跨模态注意力层，两者都必须看到完整的视觉 token 集合才能做全局 TopK 与全局归一化，因此视觉侧天然不适合在 token 维度上切分。</p>\n<p>工程上的常见做法是视觉编码器走 DP 或小规模 TP，LLM 主干走 TP×PP，MoE 层再叠加 EP。视觉 token 从 N_v 压到 K 之后，跨模态注意力的序列长度骤降，TP 组内每卡持有的视觉侧 KV 分片也随之缩小，这直接改变了 TP 的收益曲线：TP 通信量按每层激活大小分摊，序列越短，单次 All-Reduce 的消息越小，延迟中固定开销占比上升。用公式表述，TP 组内一次 All-Reduce 的代价近似为</p>\n<div class=\"formula\">$$T_{\\text{AR}} \\approx \\alpha + \\beta \\cdot \\frac{S \\cdot H \\cdot b}{G}$$</div>\n<p>其中 α 是启动延迟，β 是带宽倒数，S 为序列长度，H 为隐藏维，b 为字节数，G 为 TP 度。ERA 把 S 从 N_v 降到 K，等于把 β 项压小，但 α 项不动——这正是“压缩后 TP 度该不该调小”的判断依据。举例：一个 8 卡 TP 组处理高分辨率图像输入，压缩前每层 All-Reduce 消息较大、带宽受限；压缩后消息缩小到启动延迟主导，此时把 TP 度从 8 降到 4、把省下的卡转去做 DP 提高并发，往往比维持 8 卡 TP 更划算。代价是 PP 的流水气泡会随 PP 度变化重新分布，需要重算每段层数与微批数。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-33\">三十三 · NVLink 5 与 NVSwitch：机内带宽不是无限</h3>\n<p>GB200/GB300 NVL72 机柜内通过 NVLink 5 与 NVSwitch 构成全互联域，单卡对外带宽远高于 PCIe 代际，使得 TP 与 EP 的 All-Reduce、All-to-All 可以落在机内完成而不出机柜。但“带宽高”不等于“通信免费”：NVSwitch 是全交叉结构，任意两卡通信都经过交换芯片，跳数固定但交换带宽是共享资源。当 TP 组、EP 组、DP 组的集合在同一时刻重叠，All-Reduce 与 All-to-All 会争抢同一批链路，形成集合通信的拥塞。</p>\n<p>对 ERA 的直接含义是：整流步骤需要在跨模态注意力层做一次全局求和归一化，若视觉侧按 TP 切分，则每个分片只持有部分保留 token 的注意力权重，必须先做一次 All-Reduce 得到全局分母再各自相除，否则各分片归一化基准不一致，跨模态对齐被破坏——这是失败模式里明确点出的风险。伪代码思路是：先在本地对保留位置求部分和 s_g，All-Reduce 求和得 S，再用 a_i/S 做整流。这次 All-Reduce 的消息量只有每头一个标量，α 主导，代价低但同步点强，会插入一次全局屏障。若把它与相邻层的 TP All-Reduce 合并成一次批处理集合通信，可以摊薄启动开销；若单独发，则在低延迟 SLO 下每次屏障都是一次抖动源。</p>\n<p>代价判断：机内 NVLink 5 域让 TP=8 的 All-Reduce 不再是吞吐瓶颈，真正的瓶颈转移到“同步点数量”与“集合通信重叠度”。整流引入的额外屏障若不能与前向计算重叠，端到端首 token 延迟会增加一个与层数成正比的固定项，压缩比越高、单层计算越短，这个固定项占比越大。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-34\">三十四 · All-to-All 与 EP：MoE 层的通信形态</h3>\n<p>当 LLM 主干是 MoE 结构时，EP 切分带来的是 All-to-All：每个 token 的隐状态要被路由到持有对应专家的卡上，算完再散回。All-to-All 的代价与“每卡发出的 token 数 × 隐藏维 × 字节数”成正比，且是双向的，比 All-Reduce 更难与计算重叠，因为它依赖路由结果，路由又依赖上一层输出，形成串行链。</p>\n<p>ERA 在这里的作用是间接的：视觉 token 从 N_v 压到 K，意味着进入 MoE 层的序列变短，All-to-All 的消息量按比例下降。但要注意路由的负载不均衡——视觉 token 的熵分布与文本 token 不同，高熵保留的 token 在语义上更“细”，其路由分布可能与文本 token 显著不同，导致某些专家在预填阶段被集中命中，形成 EP 组内的热点卡。热点卡的 All-to-All 发送队列变长，整组被最慢卡拖住。工程上的缓解手段是容量因子与 token 丢弃策略，但这会反过来影响 ERA 保留的细粒度 token 的完整性，需要在精度与通信均衡之间做取舍。举例：视频输入逐帧剪枝后，若某帧保留的 token 恰好集中路由到少数专家，该帧的预填延迟会明显高于均值，批内延迟方差被放大——这与材料中“帧间熵分布不均、时序一致性未验证”的局限是同一件事的通信侧表现。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-35\">三十五 · NIXL 传输与分离式部署</h3>\n<p>分离式预填/解码把预填与解码放在不同实例上，KV cache 需要跨节点搬运，NIXL 就是承担这类点对点传输的库。对 ERA 来说，分离式部署带来一个额外好处：视觉编码器与熵估计可以独立成一个预填侧服务，压缩后的 K 个 token 及其整流所需的注意力统计量一起传给解码侧，传输量按 K 而非 N_v 计。传输代价近似为</p>\n<div class=\"formula\">$$T_{\\text{xfer}} \\approx \\frac{K \\cdot H \\cdot b_{\\text{kv}} \\cdot L}{B_{\\text{link}}}$$</div>\n<p>其中 L 为层数，b_kv 为每元素字节数，B_link 为链路带宽。K 越小，跨节点 KV 搬运越轻，分离式部署的收益越明显；反之若 K 接近 N_v，传输成为瓶颈，分离式反而不如一体化部署。这里有一个容易忽略的点：整流是前向修正，不改变权重，因此解码侧不需要重算整流，只需接收已整流的注意力分布或已压缩的 KV；但若整流在预填侧完成、解码侧继续做自回归注意力，则两侧对“有效 token 集合”的定义必须一致，否则解码步的注意力会重新泄漏到已剪位置。这要求传输的不只是 KV 张量，还有一份保留掩码，掩码本身很小但必须与 KV 同步到达，否则出现掩码与 KV 不一致的窗口。</p>\n<p>代价判断：NIXL 传输的瓶颈通常在链路带宽与消息粒度，而非 CPU。把 K 个 token 的 KV 按页打包、与掩码同批发送，可以减少小消息的启动开销；若按 token 逐条发送，启动延迟会吞掉压缩带来的全部收益。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-36\">三十六 · 通信何时成为瓶颈：三个判据</h3>\n<p>把上面的机制收敛成可操作的判断，通信成为瓶颈通常满足以下条件之一。其一是计算通信比跌破阈值：单层计算时间 T_comp 与集合通信时间 T_comm 之比小于 1 时，GPU 在等通信。ERA 压缩序列会同时压低 T_comp 与 T_comm 中的 β 项，但 T_comm 的 α 项不变，因此压缩比越高，越容易触发这一条。其二是同步点密度：整流屏障、TP All-Reduce、EP All-to-All 在同一微批内串联出现，且无法与计算重叠，此时瓶颈不是带宽而是延迟链。其三是集合通信集合重叠：TP 组与 EP 组的卡集合在 NVSwitch 上交叉，同一时刻的 All-Reduce 与 All-to-All 争抢交换带宽，表现为有效带宽低于标称值。</p>\n<p>对应的工程动作：第一，按压缩后的 K 重算 TP 度，把省下的卡转 DP，用并发换吞吐；第二，把整流的分母 All-Reduce 与相邻层集合通信合并，减少屏障数量；第三，EP 侧监控专家命中分布，对视觉 token 的路由热点做容量因子调整，但要接受由此带来的 token 丢弃对细粒度语义的损伤；第四，分离式部署时按 K 估算传输量，K 大时退回一体化部署。表格给出四种并行形态在 ERA 场景下的主要代价面：</p>\n<table class=\"mini\"><thead><tr><th>并行形态</th><th>通信原语</th><th>ERA 相关代价</th><th>何时成瓶颈</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>整流分母需全局求和，插入屏障</td><td>K 小、单层计算短，α 主导</td></tr><tr><td>EP</td><td>All-to-All</td><td>视觉 token 路由热点导致组内拖尾</td><td>预填阶段专家命中集中</td></tr><tr><td>PP</td><td>点对点激活传递</td><td>流水气泡随段数重分布</td><td>微批数不足、段间负载不均</td></tr><tr><td>DP</td><td>无（或梯度侧，推理期不涉及）</td><td>并发提升，KV 显存按副本计</td><td>显存而非通信受限</td></tr></tbody></table>\n<p>最后落在具体机制上：ERA 的整流归一化在 TP 下必须做一次全局求和，这次 All-Reduce 的消息量极小但同步性极强，它决定了压缩收益能否真正转化为端到端延迟下降。若把这次求和融合进跨模态注意力的 kernel、与相邻层的集合通信批处理，通信开销可被摊薄；若单独发射，则每层一次屏障会把高压缩比下的计算节省吃掉。工程判断的标准很直接：测量整流屏障前后的首 token 延迟差，若差值随层数线性增长且不可重叠，就应优先做 kernel 融合而不是继续加大压缩比。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-37\">三十七 · 整流归一化的并行切分代价与通信临界点</h3>\n<p>ERA的整流式看似是逐行softmax的局部操作，但分母Σ_{j∈K}a_j是沿视觉token维度的全局求和。当LLM跨模态注意力层按张量并行切分时，视觉侧注意力头被分散到多个rank上，每个rank只持有部分头的权重与部分KV分片，整流分母必须在头并行组内做All-Reduce才能保证各分片归一化一致——否则同一保留token在不同rank上得到不同缩放因子，跨模态对齐在数值层面直接破裂。更麻烦的是，剪枝掩码𝟙[i∈K]本身依赖熵排序结果，而熵估计发生在视觉编码器侧，若视觉编码器与LLM采用不同的并行拓扑（例如编码器DP、LLM走TP+EP），掩码需要跨拓扑广播，这条路径上的集合通信与整流All-Reduce叠加，构成一条不可忽略的同步链。以GB200 NVL72的NVLink 5域内All-Reduce为例，单次小消息延迟虽低，但整流发生在每一层跨模态注意力上，层数×头并行组数的通信次数会随模型深度线性累积，在首token延迟SLO收紧时，这条链的暴露时间直接吃掉剪枝换来的预填收益。</p>\n<p>把通信代价写成可判断的形式：设整流All-Reduce的消息量为M（与保留token数K、头维度、分片数成正比），层数为L，头并行组内rank数为T，则单请求整流同步开销近似为<div class=\"formula\">$$T_{\\text{rect}} \\approx L \\cdot \\alpha(M, T) + \\frac{L \\cdot M}{B_{\\text{nvlink}}}$$</div>其中α为集合通信启动延迟项，B为NVLink 5有效带宽。剪枝带来的预填节省为ΔT_pre ∝ (N_v − K)·d·L/B_compute。判据很直接：当T_rect > ΔT_pre时，ERA在端到端首token延迟上是负收益，此时应把整流分母改为rank-local近似（牺牲少量归一化精度换取零同步），或把整流下沉到单rank内完成、仅在输出侧做一次轻量校正。视频多帧场景更危险：帧间熵分布不均使K在请求内波动，批内不同请求的整流消息量不一致，All-Reduce被最慢请求拖尾，连续批处理的批内延迟方差随之放大。</p>\n<p>EP与PP进一步改变失效边界。跨模态注意力若走专家并行，视觉token被路由到不同专家分片，整流分母的求和范围跨越All-to-All边界，此时需在All-to-All前后各做一次局部归一化再合并，通信量翻倍；PP把跨模态层切到不同stage，整流掩码必须随激活一起沿流水线传递，stage间点对点传输虽走NVLink但引入气泡。NIXL在此处的价值是把视觉编码器与LLM分离部署时的token与掩码传输做成零拷贝RDMA路径，避免主机侧中转；但NIXL只降低传输成本，不消除整流同步的语义约束。工程判断落在一条具体机制上：整流分母的归约范围必须与并行切分对齐——头并行内做All-Reduce、专家并行内做All-to-All后局部归一、流水线stage间传递掩码而非重算熵，三者选其一按拓扑匹配；当K小到使消息量落入NVLink 5的延迟主导区（小消息带宽利用率低），通信成为瓶颈的临界点由层数与头并行组数决定，此时应优先关闭整流或改用rank-local归一化，把省下的同步时间让给批调度器提高并发。</p>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-38\">三十八 · 精度塌陷的三种签名与熵尺度错位</h3>\n<p>ERA 的精度塌陷在服务侧不会以单一指标出现，而是分成三种可区分的签名，定位手段不同。第一种是<strong>跨层熵尺度错位</strong>：熵分数 <span class=\"inline\">$\\mathcal{S}_i$</span> 的绝对值随层变化，浅层注意力弥散、熵普遍偏高，深层注意力集中、熵普遍偏低。若把各层熵分数放进同一个池子做全局 TopK，排序结果会被层间尺度差主导，深层token被系统性挤出预算，而深层恰恰承载跨模态对齐的关键证据。签名是：压缩比正常、整流开关打开、但图文匹配类任务掉点明显，且掉点随层数加深而放大。诊断办法是对每层分别做分位数归一化后再排序，或在监控里按层记录保留token的层分布直方图，一旦直方图向浅层倾斜即为该模式。代价上，逐层归一化需要每层一次排序，若在视觉编码器末端一次性做全局排序则省掉这部分开销，但换来的是上述偏差。</p>\n<p>第二种是<strong>整流归一化不一致</strong>。公式 <span class=\"inline\">$\\tilde{a}_{i}={a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}/{\\sum_{j\\in\\mathcal{K}}a_{j}}$</span> 的分母是保留集合上的全局求和。在张量并行下，视觉侧注意力头被切到不同 rank，若各 rank 只对本分片的保留权重求和再归一化，分母偏小，整流后权重整体偏大，跨模态注意力被过度锐化。签名是：单卡部署精度正常，切到多卡张量并行后精度跳变，且跳变幅度与并行度相关。定位方式是抓一层整流前后的注意力熵对比：整流后熵应略降但不该骤降，若骤降即为分母不一致。修复用 all-reduce 求全局分母，代价是每层一次小规模集合通信，在 NVLink 5 域内可忽略，但跨节点部署时会进入关键路径。</p>\n<p>第三种是<strong>极低预算下的信息不可恢复</strong>。整流只能重分配注意力质量，无法重建被剪除token承载的细粒度信息。签名是精度随压缩比呈非线性悬崖：预算从中等降到极低时掉点突然加速。这不是bug而是边界，监控上应把压缩比与精度做成二维曲线，在悬崖拐点之前设定预算下限，而不是等精度塌陷后再回滚。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-39\">三十九 · OOM 与批抖动的耦合定位</h3>\n<p>ERA 部署后最典型的显存事故不是稳态OOM，而是<strong>批抖动引发的瞬时OOM</strong>。机制链条是：批调度器按压缩后序列长度重算每请求 KV cache 占用并提高并发，但视觉token压缩比是<strong>逐请求变化</strong>的——高熵图像保留token多、低熵图像保留少。若调度器用历史平均压缩比估算显存预算，遇到一批高熵请求（细节密集图像、多帧视频）时实际占用超出估算，触发OOM或被迫抢占。公式化地，单批显存需求为 <span class=\"inline\">$M=\\sum_{r\\in B} (K_r + L_r)\\cdot c_{\\text{kv}} + M_{\\text{act}}$</span>，其中 <span class=\"inline\">$K_r$</span> 是该请求整流后的视觉token数、<span class=\"inline\">$L_r$</span> 是文本长度、<span class=\"inline\">$c_{\\text{kv}}$</span> 是每token KV 字节数。抖动来自 <span class=\"inline\">$K_r$</span> 的方差，而非均值。</p>\n<p>定位手段是给调度器加一层<strong>压缩比预检</strong>：在准入阶段先跑轻量熵估计得到 <span class=\"inline\">$K_r$</span> 的上界，再决定是否放入当前批。代价是准入路径多一次视觉侧前向，若熵估计已融合进视觉编码器则近乎免费，否则会拉长首token延迟。更省的做法是按请求类型分桶（单图/多图/视频帧数区间）维护压缩比的分位数而非均值，用 P95 估算显存，牺牲少量并发换取不OOM。批抖动的另一个来源是整流开关的灰度：同一批里部分请求开整流、部分不开，序列长度分布混合，调度器按统一预算分配会失准，灰度期应按开关状态分池调度。</p>\n<p>监控上应区分两个指标：<strong>批内压缩比方差</strong>与<strong>显存水位峰值</strong>。前者升高是OOM前兆，后者是结果。只看水位会在事故发生时才发现，看方差可以提前扩容或降并发。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-40\">四十 · 尾延迟：熵估计的算子开销落在关键路径</h3>\n<p>ERA 的尾延迟问题源于熵估计与排序是<strong>逐请求串行</strong>的前向开销，且其规模随 <span class=\"inline\">$N_v$</span> 线性增长。对短文本、单图的轻请求，视觉token占比高，熵估计开销相对预填收益的比例被放大；对长文本请求，解码占主导，剪枝收益本就有限。因此尾延迟的分布是双峰的：轻请求被熵估计拖慢，重请求被解码拖慢。定位办法是按请求的视觉token数与文本token数做二维分桶，分别统计 P99 首token延迟，若轻请求桶的 P99 显著高于中位，即为熵估计落在关键路径。</p>\n<p>工程判断上，熵估计应尽量融合进视觉编码器的最后一个 attention kernel，把熵计算作为 epilogue 的一部分，避免额外一次全序列读写。若无法融合，退而求其次是把熵估计与排序放到独立的<strong>预取阶段</strong>，与文本预处理并行，用流水掩盖。代价是显存里同时驻留原始 <span class=\"inline\">$N_v$</span> 与压缩后 <span class=\"inline\">$K$</span> 两份视觉特征，峰值显存上升，需在预算里预留这部分。视频场景下逐帧独立剪枝还会引入帧间时序不一致，表现为同一请求内不同帧保留token的语义粒度不齐，尾延迟方差随帧数增大，监控应记录每请求的帧间压缩比极差。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-41\">四十一 · 静默降级：没有报错但质量在滑</h3>\n<p>最危险的一类失败是<strong>静默降级</strong>：服务不报错、吞吐正常、延迟达标，但输出质量在缓慢下滑。ERA 的静默降级有三个来源。其一是整流开关被配置层默认关闭而无人察觉——压缩照常发生、整流未生效，精度损失被压缩收益掩盖，直到业务方反馈答非所问才暴露。其二是熵估计的数值精度：若熵计算在 FP8 下做，<span class=\"inline\">$p_{ij}\\log p_{ij}$</span> 在概率接近0或1时对量化误差敏感，熵排序在边界token上抖动，保留集合逐请求不稳定，表现为同一图像重复请求得到不同答案。其三是分页 KV cache 与压缩后长度更新不同步，页表残留旧长度导致注意力读到已剪除位置的脏数据，输出看似合理实则错位。</p>\n<p>监控静默降级不能只靠延迟与吞吐，必须建立<strong>在线质量探针</strong>：固定一小批黄金请求周期性回放，比对输出与基线的一致性；同时记录整流前后注意力熵的差值，正常应为一个小的正数区间，若差值趋近于零说明整流未生效，若异常大说明归一化分母出错。代价是探针请求占用算力，通常放在低峰期或独立小池。回滚策略上，ERA 作为推理期插件天然支持按请求粒度回滚：把整流开关与预算K做成请求级配置，发现某类负载降级时只对该负载关闭压缩，不必整服务回退。这比回滚模型版本代价低得多，但要求配置系统支持热更新且调度器能按配置分池。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-42\">四十二 · 诊断顺序与回滚的工程判断</h3>\n<p>面对一次精度或稳定性事故，推荐的定位顺序是：先看<strong>压缩比分布</strong>是否偏离基线（区分负载变化与方法失效），再看<strong>整流前后熵差</strong>（区分整流未生效与归一化错误），再看<strong>保留token的层分布</strong>（区分熵尺度错位），最后看<strong>并行度与开关灰度</strong>（区分部署配置问题）。这个顺序把最便宜的指标放前面，避免一上来就抓kernel。回滚的最小单元应是<strong>请求级配置</strong>而非服务级：把 token 预算 K、整流开关、逐层归一化开关做成三个独立旋钮，事故时按负载类型逐项关闭，保留其余收益。代价是配置组合增多、测试矩阵膨胀，需要把旋钮数量控制在可组合验证的范围内。</p>\n<p>最后落在具体机制上：ERA 的失败模式几乎全部集中在<strong>熵排序的跨层可比性</strong>与<strong>整流归一化的全局一致性</strong>这两个点上，前者决定保留集合对不对，后者决定保留下来后注意力分得对不对。工程上应把这两点做成可观测的一等公民——每层保留直方图与整流前后熵差作为常驻指标，而不是等精度塌陷后反推。至于极低预算下的信息不可恢复，那不是可修的失败模式，而是需要在容量规划阶段就用压缩比-精度曲线划定的预算下限。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-43\">四十三 · 失效边界：从熵排序偏差到整流归一化在切分下的不一致</h3>\n<p>ERA 的失效并不集中在单一环节，而是沿“熵估计—排序—整流”这条链路分布。第一类失败是<strong>跨层熵尺度不可比</strong>：不同层注意力熵的量纲与弥散程度不同，若把多层熵分数拼进同一个排序池做全局 TopK，高熵层会系统性挤占低熵层的保留名额，等价于把预算偏移到本不该优先保留的层。诊断方法是按层分别统计保留率与整流前后熵差，若某层保留率长期偏离配置的层内预算比例，即为尺度失配。第二类失败是<strong>整流归一化在张量并行下不一致</strong>：$\\tilde{a}_{i}={a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}\\big/{\\sum_{j\\in\\mathcal{K}}a_{j}}$ 的分母是保留集合上的全局和，当视觉侧注意力按头或按序列切分到多个 rank 时，各分片只对本地可见的保留 token 求和，归一化结果彼此不等，跨模态对齐被破坏且表现为精度缓慢塌陷而非崩溃，属于典型的静默降级。</p>\n<p>第三类失败是<strong>极低 token 预算下的精度塌陷</strong>：整流只能把注意力质量在被保留集合上重新分配，无法恢复被剪除 token 承载的细粒度信息，压缩比越高，塌陷越确定。这类失败在监控上表现为整流后注意力熵异常偏低（注意力过度集中到少数 token）与首 token 延迟下降但输出质量指标下滑同时出现。第四类失败是<strong>视频多帧的时序不一致</strong>：逐帧独立剪枝使各帧保留集合不连续，帧间时序信号被切断，表现为批内延迟方差上升与长视频问答的答案漂移。第五类是<strong>OOM 与批抖动</strong>：批调度器按压缩后长度重算显存预算，但若熵估计的临时缓冲、整流掩码与分页 KV 页表未同步按 K 收缩，实际占用高于预算估计，触发重调度与批抖动，尾延迟出现尖峰。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>跨层熵尺度偏差</td><td>某层保留率偏离层内预算</td><td>分层保留率与熵分布直方图</td><td>改为层内独立 TopK</td></tr><tr><td>整流切分不一致</td><td>精度缓降、无报错</td><td>对比单卡与多卡整流分母</td><td>关闭整流或改全局归约</td></tr><tr><td>极低预算塌陷</td><td>整流后熵骤降、质量指标下滑</td><td>按 K 扫描质量曲线</td><td>上调 K 至拐点以上</td></tr><tr><td>批抖动与 OOM</td><td>尾延迟尖峰、重调度频繁</td><td>临时缓冲与页表占用对账</td><td>回退并发上限、关分页收缩</td></tr></tbody></table>\n<p>工程上应把 K、整流开关、熵估计所在层做成三个可独立回滚的服务侧配置，并为每个请求记录压缩比、整流前后熵、预填延迟与批内位置，使尾延迟尖峰能直接归因到某一配置组合；熵估计若未能融合进视觉编码器或注意力 kernel，其额外前向与排序开销在低延迟 SLO 下会先于精度问题暴露，此时应优先回滚整流开关而非 K，以区分“算子开销”与“对齐损失”两类代价。</p>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-44\">四十四 · 口径的三层结构：模型档、硬件档、负载档</h3>\n<p>读ERA这类视觉token剪枝工作的基准数字，第一件事不是看加速比，而是把口径拆成三层：模型档（视觉编码器分辨率与帧数、LLM规模、量化配置）、硬件档（B200单卡、B300单卡、GB200 NVL72机柜级）、负载档（batch大小、并发请求数、输入是单图还是多帧视频）。三层中任何一层变动，同一组TTFT/吞吐数字就失去可比性。原因在于ERA的收益来源是视觉token从N_v降到K，而N_v由分辨率与帧数决定，K由服务侧配置决定——这两个量都不属于模型权重，属于部署参数。因此一篇论文若只报“端到端加速X倍”而不交代N_v、K、batch与并发，这个X倍在Blackwell上无法复现，也无法与其他压缩方法横向比较。</p>\n<p>具体机制上，视觉token压缩改变的是预填阶段的序列长度。设单请求视觉token数为N_v、文本token数为N_t、压缩预算为K，则压缩前后预填计算量之比近似为</p>\n<div class=\"formula\">$$r_{\\text{prefill}} \\approx \\frac{K + N_t}{N_v + N_t}$$</div>\n<p>当N_t远小于N_v（高分辨率单图、多帧视频）时，r趋近K/N_v，压缩收益接近线性；当N_t与N_v同量级（长提示、短视觉输入）时，收益被文本侧稀释。这就是为什么同一套ERA配置在“一图一短问”和“多帧长问”两种负载下报出的加速比不可比——分母不同。工程判断：看到任何加速数字，先问N_v/N_t比值，再问K的取值，两者缺一不可。</p>\n<p>硬件档位的影响则体现在另一个维度。B200与B300的差异主要在算力与显存带宽配比，而ERA的预填收益同时受算力（注意力矩阵计算）与带宽（KV cache写入）约束。在算力受限的配置下，压缩N_v直接减少MMA工作量，收益明显；在带宽受限的配置下，压缩减少的是KV cache页写入量，收益体现在显存占用与页表压力上。GB200 NVL72的机柜级部署又把视觉编码器与LLM分离到不同GPU上，此时视觉侧压缩发生在编码器输出与跨模态注意力之间，跨节点传输的视觉token数量同步下降——这是一条NVLink 5带宽侧的收益，与单卡内的算力收益不是同一个口径，不能相加成一个“总加速比”。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-45\">四十五 · 指标各自的敏感面：TTFT、TPOT、吞吐、显存、功耗</h3>\n<p>五个指标对ERA的敏感度完全不同，混报会误导容量规划。TTFT（首token延迟）由预填阶段主导，视觉token压缩直接缩短预填，是ERA最直接的受益指标；TPOT（每输出token时间）由解码阶段主导，视觉token已在KV cache中，压缩只降低每步注意力的KV读取量，收益随K/N_v下降而递减，在长输出场景中被摊薄。吞吐（tokens/s或requests/s）取决于批调度器能否用省下的显存提高并发批大小，这是一个二阶效应：压缩本身不提高吞吐，压缩释放的KV cache预算被调度器换成更大batch才提高吞吐。显存占用是压缩的一阶效应，KV cache按K而非N_v分配，页表项同步减少。功耗则最容易被忽略：预填阶段MMA利用率下降会降低瞬时功耗，但若调度器把省下的算力换成更大batch，功耗可能回升甚至超过压缩前——功耗口径必须绑定batch与并发，单独报“省电”没有意义。</p>\n<p>用一个具体例子说明二阶效应的量级关系。设某请求N_v=4096、N_t=64、K=512，则r≈576/4160≈0.138，预填计算量降到约七分之一，TTFT随之下降。但若调度器维持原batch不变，吞吐不变、显存省下、功耗下降；若调度器把batch扩大约7倍以填满释放的显存，则吞吐上升、TTFT可能因批内竞争回升、功耗回到原水平附近。两种策略报出的“加速比”一个在延迟侧、一个在吞吐侧，数值不可互换。ERA材料未给出任何具体数字，因此这里只能给出比值结构，不能给出绝对倍数——这正是本部分要强调的读法：结构可比，绝对值不可比。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>ERA作用路径</th><th>敏感条件</th><th>易被误读之处</th></tr></thead><tbody><tr><td>TTFT</td><td>预填序列N_v→K</td><td>N_v≫N_t</td><td>与batch耦合，大batch下TTFT回升</td></tr><tr><td>TPOT</td><td>解码期KV读取量下降</td><td>长输出、K/N_v小</td><td>收益被输出长度摊薄</td></tr><tr><td>吞吐</td><td>调度器用省下显存扩batch</td><td>显存受限而非算力受限</td><td>压缩本身不产生吞吐</td></tr><tr><td>显存</td><td>KV cache按K分配</td><td>分页KV页表同步更新</td><td>未计熵估计临时缓冲</td></tr><tr><td>功耗</td><td>预填MMA利用率变化</td><td>batch策略</td><td>扩batch后功耗回升</td></tr></tbody></table>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-46\">四十六 · 熵估计与整流的算子开销如何进入口径</h3>\n<p>ERA的收益不是免费的：熵估计需要对视觉token做一次额外前向并排序，整流需要在跨模态注意力层做掩码与重新归一化。这两项开销若不能融合进视觉编码器或注意力kernel，就会以额外kernel启动与中间张量写回的形式出现在TTFT里，抵消部分预填收益。设熵估计与排序的耗时为T_ent、整流耗时为T_rect、原预填耗时为T_pre，则实际TTFT改善为</p>\n<div class=\"formula\">$$\\Delta \\text{TTFT} \\approx T_{\\text{pre}}(1 - r_{\\text{prefill}}) - T_{\\text{ent}} - T_{\\text{rect}}$$</div>\n<p>当r_prefill很小（高压缩比）时，减号后两项的相对权重上升；在低延迟SLO下，T_ent与T_rect若各占原预填的百分之几，就可能把净收益压到很小。这就是为什么“压缩比越高越好”是错误口径：压缩比提高会同时提高T_ent（更多token参与排序）与整流误差（更多信息被剪除），净收益存在拐点，而材料未给出该拐点的数值。工程上可判断的是：熵估计若能作为视觉编码器最后一个block的旁路读出、整流若能作为注意力softmax后的原地归一化，两项开销可压到接近零；若作为独立kernel插入，则必须在基准中单列这两项耗时，否则报出的TTFT改善不可复现。</p>\n<p>整流还有一个口径陷阱：它只作用于视觉侧注意力，不改变LLM主干权重，因此在张量并行切分下，归一化的求和必须跨分片一致。若各分片独立归一化，各分片看到的保留位置权重和不同，整流后的注意力分布与单卡结果不一致，精度口径就与单卡基准不可比。基准表若未注明并行度与整流实现方式，其精度数字只能在同一并行拓扑内自比，不能跨拓扑引用。同理，整流开关关闭时的精度是剪枝裸精度，开启时是补偿后精度，两者必须成对报告，单独报开启后的数字会掩盖剪枝本身的损失幅度。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-47\">四十七 · 哪些提升不可比：四类典型错配</h3>\n<p>第一类错配是压缩比口径不同。以N_v为分母报“保留12.5%token”与以K/N_t为分母报“序列缩短X倍”是两件事，前者描述视觉侧，后者描述整条序列，后者在小N_t时严重高估收益。第二类错配是基线不同：与未压缩的原MLLM比，得到的是ERA的绝对收益；与按注意力权重排序的剪枝比，得到的是熵准则相对注意力准则的增量收益。这两个数字常被混用，但后者才是ERA的核心主张所在，前者包含了所有视觉token压缩方法的共同收益。材料未给出基线方法，因此任何“相对提升”都无法归因到熵准则本身。</p>\n<p>第三类错配是精度口径。视觉token剪枝的精度损失在不同任务上分布极不均匀：需要细粒度细节的任务（小目标、密集文字、图表读数）对剪枝敏感，粗粒度场景描述则不敏感。若基准只报一个平均精度，高熵保留策略的收益会被平均掉；若只报敏感任务，又会夸大整体损失。可判断的工程口径是分任务列出，并同时给出整流开/关两组，才能看出整流补偿了多少、剩余损失多少。第四类错配是硬件与量化配置：ERA可与NVFP4/FP8量化、分页KV cache共存，但量化本身改变注意力分布的数值精度，熵估计在低精度下的排序稳定性未经验证；若基准在FP16下测熵排序、在NVFP4下测端到端，两组数字的精度口径不一致。</p>\n<ul>\n<li>压缩比分母：N_v还是N_v+N_t，决定收益被高估的幅度。</li>\n<li>基线选择：未压缩原模型 vs 注意力排序剪枝，归因不同。</li>\n<li>精度聚合：平均精度掩盖任务间方差，需分任务并成对报整流开关。</li>\n<li>量化与并行：熵排序数值稳定性、整流跨分片归一化一致性，均需在基准中注明。</li>\n</ul>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-48\">四十八 · 视频多帧负载下的口径特殊性</h3>\n<p>视频输入把口径问题放大。逐帧独立剪枝时，每帧的熵分布不同，保留的token集合在帧间不连续，跨帧时序对齐可能被破坏；而批调度器看到的是请求级总token数，帧间token数不均会造成批内延迟方差。设请求含F帧、每帧N_f个视觉token、总预算K_total，若按帧均分预算则每帧K_total/F，若按帧内熵全局排序则某些帧可能被整帧剪空。两种策略的TTFT相近，但时序一致性完全不同，基准若不注明预算分配方式，视频场景的精度数字不可比。</p>\n<p>具体代价上，视频预填的KV cache写入量随F线性增长，ERA把总量压到K_total后，页表项与显存占用同步下降，这是显存侧最直接的收益；但熵估计需要对F×N_f个token排序，T_ent随F增长，在长视频、低延迟SLO下这项开销可能成为主导。工程判断：视频场景应把预算分配策略（帧均分 vs 全局排序）与熵估计所在层作为两个独立配置项写入基准表，并单列T_ent占TTFT的比例；材料未给出时序一致性与批内延迟方差的实测数据，因此任何视频加速比都只能视为机制推断，不能作为容量规划输入。</p>\n<p>最后落到一个可执行的读法：拿到ERA的任何基准表，先核对N_v、N_t、K、batch、并发、并行度、量化配置七项是否齐全，缺一项则该表的TTFT与吞吐只能内部自比；再核对整流开关与熵估计层是否成对报告，缺一项则精度数字无法归因；最后核对熵估计与整流耗时是否单列，缺一项则端到端加速比包含未计量开销。这七项加三项共十个字段，构成ERA在Blackwell上可复现基准的最小口径集——字段不全的数字不是错，是不可比。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-49\">四十九 · 基准口径与失效边界：ERA 的收益在什么条件下才成立</h3>\n\n<p>评估 ERA 时首先要承认一个事实边界：材料未给出数据集、基线、精度与吞吐的任何可核验数字，因此任何“加速比 X 倍、精度掉 Y 点”的说法都不成立。可比的只有机制层面的量：视觉 token 从 N_v 压到 K 后，预填阶段的自注意力计算量按 O(N_v²) 降到 O(K²)，KV cache 中视觉侧占用按 K/N_v 线性下降。端到端加速比由此可写成 <span class=\"formula\">$$S=\\frac{T_{\\text{prefill}}(N_v)+T_{\\text{decode}}}{T_{\\text{prefill}}(K)+T_{\\text{decode}}+T_{\\text{entropy}}+T_{\\text{rect}}}$$</span> 分母里多出的熵估计与整流两项决定了 S 的上界；当 T_decode 占主导（长输出、小图像）时，S 趋近 1，剪枝几乎无感。这就是为什么口径必须绑定“视觉 token 占比”与“输出长度”两个变量，脱离它们谈吞吐提升不可比。</p>\n\n<p>硬件档位与并发口径同样要写清。B200/B300 单机与 GB200/GB300 NVL72 机柜的差异不在算力峰值，而在可承载的并发批规模与 KV cache 分页压力：压缩后序列变短，批调度器按 K 重算每请求显存占用，才能把释放出的显存换成更大 batch。若报告吞吐时沿用压缩前的 batch 配置，等于把收益藏起来；若报告 TTFT 时混入解码阶段，则把预填收益稀释。可比的报告应固定：模型与量化档（NVFP4/FP8 沿用原配置）、输入分辨率与帧数、token 预算 K、batch 与并发上限、以及 TTFT/TPOT/吞吐/显存/功耗五项指标各自独立列出。功耗一项尤其不能省——熵估计是额外前向，若融合失败，SM 占用上升会直接反映在每 token 能耗上。</p>\n\n<p>失效条件集中在三处。其一，层间熵尺度不可直接比较：不同层注意力熵的分布范围不同，跨层统一排序会引入偏差，工程上应逐层归一化或只在末层取熵，否则“高熵保留”的准则在深层退化为近似随机。其二，整流在张量并行下要求全局求和一致：<span class=\"formula\">$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}}$$</span> 分母若按分片局部求和，各 rank 归一化结果不一致，跨模态对齐反而被破坏，这属于静默精度损失，基准里必须用整流前后注意力熵的偏差做监控项。其三，极低 K 下整流只能重分配权重，无法恢复被剪除的细粒度信息，精度随压缩比单调恶化，材料未给该拐点数值，部署时应把 K 设为可回退的运行时参数而非编译期常量。</p>\n\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比做法</th><th>不可比做法</th></tr></thead><tbody><tr><td>batch/并发</td><td>按压缩后 K 重算显存后定 batch</td><td>沿用压缩前 batch 报吞吐</td></tr><tr><td>延迟</td><td>TTFT 与 TPOT 分开报</td><td>混算平均每 token 延迟</td></tr><tr><td>精度</td><td>固定 K 与整流开关做消融</td><td>只报最优 K 下的单点</td></tr><tr><td>视频</td><td>报帧间熵方差与批内延迟方差</td><td>只报单帧图像结果</td></tr></tbody></table>\n\n<p>视频多帧是基准里最容易被掩盖的一档：逐帧独立剪枝使各帧保留的 token 集合不同，帧间时序一致性未被材料验证，批内延迟方差会随帧内容熵分布波动而放大。工程判断是：图像负载可把 ERA 当作预填压缩插件直接叠加量化与分页 KV；视频负载则应先测帧间熵方差，再决定是否改为跨帧联合排序或固定帧间预算。至于熵估计算子，若不能融进视觉编码器或注意力 kernel，其额外延迟在低延迟 SLO 下会吃掉预填收益——这一点应在基准中单列一项“插件开销占预填比例”，而不是折进总加速比里。</p>\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-50\">五十 · 迁移到非 Qwen-VL 系架构：熵的语义先要重新标定</h3>\n<p>ERA 的熵分数 <span class=\"formula\">$$\\mathcal{S}_i = -\\sum_{j} p_{ij}\\log p_{ij}$$</span> 是在视觉编码器输出与 LLM 跨模态注意力之间那一层上算出来的。这个位置决定了它迁移时的第一个硬约束：熵的物理含义依赖该层注意力的归一化方式与 head 数。在 Qwen-VL 一类把视觉 token 直接拼进 LLM 输入序列、由因果注意力统一处理的架构里，视觉 token 的注意力分布是跨模态对齐的直接载体，熵高确实对应“语义分散、承载细节”的 token。迁到 BLIP-2 式的 Q-Former 瓶颈架构就不成立——Q-Former 已经把 N_v 压到固定数量的 query，视觉侧注意力发生在 Q-Former 内部而非跨模态层，此时对 query 输出再做熵剪枝等于在已经压缩过的表示上二次压缩，熵排序与下游对齐质量的相关性没有依据。迁到 SigLIP/CLIP 双塔加投影层的架构，则要先判断投影层是否保留了逐 token 的注意力结构；若投影是逐 token 的线性映射，熵只能在 LLM 侧算，此时 ERA 的“视觉侧轻量熵估计”前提失效，必须把熵评估挪到第一个跨模态注意力层之后，代价是多一次前向。</p>\n<p>工程判断很直接：迁移前先做一件事——在目标模型上抽一批样本，比较“按熵排序保留 top-K”与“按注意力权重排序保留 top-K”在跨模态检索式对齐指标上的差异。若两者差异不显著，说明该架构的注意力分布本身不弥散，ERA 的核心动机不成立，此时应退回更便宜的相似度合并方案，把省下的算子预算留给量化。这个标定实验的成本是几十个 batch 的前向，远低于盲目移植后调参的代价。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-51\">五十一 · 整流在张量并行与分页 KV 下的实现边界</h3>\n<p>整流公式 <span class=\"formula\">$$\\tilde{a}_{i}=\\frac{a_{i}\\cdot\\mathbb{1}[i\\in\\mathcal{K}]}{\\sum_{j\\in\\mathcal{K}}a_{j}}$$</span> 看着是逐 token 的局部运算，但在 Blackwell 多卡部署里它是一次跨分片的归约。跨模态注意力的 head 按张量并行切到不同 rank 上，每个 rank 只持有部分 head 的注意力分数；如果各 rank 独立对本地保留 token 做归一化，分母 <span class=\"formula\">$$\\sum_{j\\in\\mathcal{K}}a_{j}$$</span> 就只是分片内的和，各分片归一化后的权重之和不为一，跨模态对齐在拼接时出现系统性偏移。正确做法是在整流前对保留集合的注意力分母做一次 all-reduce（或利用 tcgen05 MMA 的归约能力在 2-SM 协作范围内完成），把全局分母广播回各 rank 再逐元素相除。这次 all-reduce 的代价是每层一次小消息通信，在 NVLink 5 域内可忽略，但在跨节点 NVLink 域外就会进入临界路径——GB200 NVL72 机柜内没问题，跨机柜的张量并行要重新评估。</p>\n<p>与分页 KV cache 的交互更微妙。视觉 token 从 N_v 压到 K 后，页表要按新长度重排；但 ERA 是推理期插件，压缩发生在预填阶段，而分页分配器通常在请求进入时就按最大序列长度预留块。若调度器不感知压缩后的实际长度，KV cache 的显存节省就落不了地——压缩只省了算力，没省显存。这要求把 K 作为请求元数据传给调度器，让块分配按压缩后长度走。代价是调度器与压缩插件之间多一个耦合点，收益是 KV 占用按 N_v→K 的比例真实下降，直接抬高并发批大小。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-52\">五十二 · 视频与多帧：逐帧独立剪枝的时序断裂</h3>\n<p>图像输入下 ERA 的熵排序是单帧内的静态问题，视频输入下它变成跨帧的一致性问题。逐帧独立取 top-K 会让不同帧保留的 token 落在不同的空间位置上：第 t 帧保留了画面左上角的高熵细节，第 t+1 帧因为运动导致熵分布平移，保留了另一块区域。对 LLM 而言，它看到的是一串在空间上不连续的视觉 token，帧间对应关系被剪断，时序推理（动作识别、视频问答里的“先后”类问题）首先受损。材料未给出时序一致性的实测数据，但从机制上可以确定：熵是逐帧局部的量，没有任何跨帧约束。</p>\n<p>可行的改法是在帧间加一个轻量的熵平滑项，例如对同一空间 patch 位置跨帧的熵做滑动平均后再排序，或把预算 K 按帧的重要性（可用帧级熵均值做代理）非均匀分配，而不是每帧均分。前者增加一次跨帧的排序前处理，后者改变预算分配逻辑。两种改法都增加预处理开销，且都需要重新标定 K 的语义——原本 K 是单帧预算，现在变成帧组预算。判断：视频场景下不建议直接套用图像版 ERA，除非服务侧能接受逐帧独立剪枝带来的时序精度损失，或愿意承担上述改法的工程成本。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-53\">五十三 · 规模上限：K 的下界由什么决定</h3>\n<p>ERA 的压缩比上限不是由熵估计精度决定的，而是由“整流只能重分配、不能恢复”这一根本限制决定的。当 K 降到某个阈值以下，被剪除的 token 承载的细粒度信息（小字、细纹理、远处目标）在保留集合里没有对应表示，整流把注意力重新归一化到剩余 token 上，只是让模型更自信地看错地方。这个阈值与任务类型强相关：文档 OCR、图表理解这类依赖局部高分辨率细节的任务，K 的下界明显高于自然图像描述类任务。材料未给出具体数值，工程上应把它当作一个必须实测的容量参数，而不是可以拍脑袋设定的超参。</p>\n<p>另一个规模上限来自熵估计开销的相对占比。设视觉编码器前向为 <span class=\"formula\">$$T_{enc}$$</span>，熵估计与排序为 <span class=\"formula\">$$T_{ent}$$</span>，预填总时为 <span class=\"formula\">$$T_{pre}$$</span>，则压缩带来的净收益近似为 <span class=\"formula\">$$T_{pre}\\cdot(1-K/N_v) - T_{ent}$$</span>。当视觉 token 在总序列中占比不高（例如文本很长的多模态请求），<span class=\"formula\">$$T_{pre}$$</span> 里视觉部分本就小，<span class=\"formula\">$$T_{ent}$$</span> 很容易吃掉全部收益。判断：ERA 的经济区间是“视觉 token 主导预填”的负载，即高分辨率图像、多帧视频、视觉密集的文档场景；文本为主、图像为辅的请求不应开启，开关应按请求特征动态决定而非全局常开。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-54\">五十四 · 跨领域迁移的取舍表</h3>\n<p>把 ERA 迁到七个推理领域时，改动点与不适用点可以按“熵语义是否成立、整流是否有跨分片归约、时序是否连续”三个维度快速判断。下表给出的是判断而非承诺，具体收益仍需在目标负载上实测。</p>\n<table class=\"mini\"><thead><tr><th>领域</th><th>迁移改动</th><th>主要风险</th></tr></thead><tbody>\n<tr><td>文档/OCR 理解</td><td>提高 K 下界，熵估计放在高分辨率切片的末层</td><td>细粒度字符被剪后整流无法恢复</td></tr>\n<tr><td>视频理解</td><td>加跨帧熵平滑或帧级预算分配</td><td>逐帧独立剪枝造成时序断裂</td></tr>\n<tr><td>GUI/屏幕代理</td><td>保留小控件区域的高熵 token，预算按区域非均匀</td><td>小目标 token 数少，熵排序不稳定</td></tr>\n<tr><td>机器人/具身</td><td>低延迟 SLO 下需把熵估计融进编码器 kernel</td><td>额外算子延迟抵消预填收益</td></tr>\n<tr><td>医学影像</td><td>熵阈值需按模态重标定，倾向保守 K</td><td>病灶细节稀疏，误剪代价高</td></tr>\n<tr><td>遥感/卫星图</td><td>大图切片后按切片分配预算</td><td>切片间熵尺度不一致</td></tr>\n<tr><td>多轮对话中的图像</td><td>图像只在首轮压缩，后续轮复用压缩结果</td><td>后续追问细节时无法回溯被剪 token</td></tr>\n</tbody></table>\n<p>这张表里最值得强调的是最后一行：多轮对话场景下，首轮压缩是不可逆的，用户后续追问“图里右下角那个数字是多少”时，被剪掉的 token 已经不在 KV cache 里，模型只能基于保留集合回答。这是 ERA 作为推理期插件的结构性局限——它不像可回溯的稀疏注意力那样保留原始表示。工程上的缓解办法是对高价值请求保留原始视觉 token 的旁路缓存（不参与注意力但留在显存），代价是显存节省打折。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-55\">五十五 · 与量化、投机解码叠加时的相互作用</h3>\n<p>ERA 声称可与 NVFP4/FP8 量化共存，机制上确实不冲突——整流不改权重，量化作用于权重与激活，两者正交。但叠加时的数值细节需要注意：整流后的注意力权重是浮点归一化结果，若下游的 KV cache 以 FP8 存储，归一化分母的精度损失会体现在跨模态对齐上，尤其在 K 很小、保留集合注意力集中时，分母的相对误差被放大。判断：低比特 KV 与激进压缩比同时开启时，应把整流后的注意力分母保留在更高精度（例如 FP16 累加），只对权重做低比特存储，这个混合精度策略的代价是少量寄存器压力，收益是避免对齐精度在压缩与量化双重作用下塌陷。</p>\n<p>与投机解码叠加则是另一回事。投机解码的收益来自解码阶段接受率的提升，而 ERA 压缩的是预填阶段的视觉 token，两者作用在不同阶段，收益可加但不互相放大。真正的相互作用在批调度：压缩后预填变短，批内请求的预填完成时间更集中，投机解码的草稿模型可以更早介入，但草稿模型的验证仍要走完整解码路径，视觉 token 压缩对解码步数没有影响。所以端到端加速比的上限由视觉 token 在总计算中的占比封顶，这个占比在长文本多模态请求里可能只有个位数百分比，此时 ERA 的收益被稀释到不可观测。工程判断：把 ERA 当作预填阶段的专项优化，不要指望它改善解码吞吐；容量规划时按“预填延迟下降、解码不变”建模，而不是按整体吞吐提升建模。</p>\n\n<h3 id=\"paper-era-entropy-guided-visual-token-prun-2026-sec-56\">五十六 · 迁移与边界：从插件假设到规模上限</h3>\n<p>ERA 的可迁移性来自它不碰权重，但这也决定了它的适用边界由“熵是否仍是有效重要性信号”这一前提划定。跨模型迁移时最需要改的不是整流公式，而是熵估计的取层位置：不同视觉编码器（ViT 系与卷积-注意力混合系）的层间熵尺度差异明显，把某一层标定出的 top-k 预算直接搬到另一模型，等于把跨层不可比的熵分数当绝对重要性用，剪枝偏差会先于精度损失暴露。迁移到新领域（如文档、遥感、医学影像）时，细粒度语义往往集中在低熵但高显著性的局部区域，此时“熵高优先保留”的准则需要与任务先验做加权，而不是原样套用。系统代价上，熵估计与排序若不能融合进视觉编码器 kernel，额外前向会直接抬高首 token 延迟，在低延迟 SLO 下这部分开销与剪枝收益是同量级的竞争项，迁移前应先测这条链路而非先测精度。</p>\n<p>失效条件可以写成一个压缩比判据。设原始视觉 token 数为 $N_v$、预算为 $K$、被剪 token 承载的有效互信息为 $I_{\\text{cut}}$，整流只能重分配注意力而不能重建信息，因此可恢复的上界满足</p>\n<div class=\"formula\">$$\\Delta_{\\text{align}} \\;\\le\\; \\frac{I_{\\text{cut}}}{N_v-K}\\cdot\\frac{1}{\\bar{\\mathcal{S}}_{\\mathcal{K}}}$$</div>\n<p>其中 $\\bar{\\mathcal{S}}_{\\mathcal{K}}$ 为保留集平均熵。该式只作定性判断：当 $K/N_v$ 很低时，分母变小、$I_{\\text{cut}}$ 变大，整流对对齐的补偿迅速饱和，精度塌陷成为结构性而非调参问题。因此 ERA 不适用于需要逐像素级细节的下游任务（小目标检测、细粒度 OCR），也不适用于视觉 token 占比本就很低、预填不是瓶颈的短文本长解码负载——此时压缩视觉侧对端到端延迟几乎无贡献，却引入了熵估计的固定开销。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动</th><th>不适用信号</th></tr></thead><tbody><tr><td>换视觉编码器</td><td>重标定熵取层与预算 K</td><td>层间熵尺度不可比</td></tr><tr><td>换领域</td><td>熵准则叠加任务先验</td><td>细节集中在低熵区</td></tr><tr><td>张量并行</td><td>整流全局求和一致</td><td>分片归一化不一致</td></tr><tr><td>视频多帧</td><td>帧间熵排序稳定化</td><td>逐帧独立剪枝致时序抖动</td></tr></tbody></table>\n<p>规模上限落在两个工程点上。其一是批调度：压缩后序列长度变化要求调度器按 $K$ 重算每请求 KV cache 占用再定并发，若沿用压缩前预算，显存会被高估、并发被人为压低，收益被调度层吃掉；反之按压缩后预算放并发，则需保证整流在张量并行切分下全局求和一致，否则各分片归一化结果不同，跨模态对齐在批内不同请求间出现漂移。其二是视频场景：逐帧独立剪枝使帧间熵排序不稳定，批内延迟方差上升，SLO 尾部被拉长，这比平均吞吐更早触及容量上限。判断标准很直接——先确认视觉 token 在预填延迟与 KV 占用中的占比，再确认熵估计能否融进现有 kernel；两条都不成立时，ERA 应作为可选开关而非默认路径部署。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">ERA: Entropy-Guided Visual</text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> Token Prunin…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · ERA: Entropy-Guided Vis… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线方法</td></tr><tr><td>主要结果</td><td>材料未给出可核验的精度与吞吐数字；从机制推断，收益主要来自视觉token数…</td></tr><tr><td>消融</td><td>材料未给出消融实验数据；可推断需消融的变量为token预算K、熵估计所在层…</td></tr><tr><td>局限</td><td>材料未给出失败模式与边界条件的量化结果；可推断的风险包括：熵估计本身引入额…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-era-entropy-guided-visual-token-prun-2026 · 共 9 个片段</p>\n";break;}}})();
